INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e94930a1-fdf7-5d5c-a5b6-e0e1597e6408', 'e81d5a55-b62b-53d6-b5e4-23fa3fee9725', 'choice', '{"en": "How do Muslims greet each other?", "bn": "মুসলমানরা একে অপরকে কীভাবে সালাম দেয়?"}', '{"options": [{"en": "As-salamu alaykum", "bn": "আসসালামু আলাইকুম"}, {"en": "Good morning", "bn": "শুভ সকাল"}, {"en": "Ma‘as-salamah", "bn": "মাআস সালামা"}, {"en": "Bismillah", "bn": "বিসমিল্লাহ"}], "correct": 0}', '{"en": "\"Spread salam among yourselves.\"", "bn": "\"তোমরা পরস্পরের মাঝে সালামের প্রসার ঘটাও।\""}', 'Sahih Muslim 54', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a41f92cb-f45c-5f20-8b6d-b2ef407609fe', 'e81d5a55-b62b-53d6-b5e4-23fa3fee9725', 'choice', '{"en": "How do you reply to \"As-salamu alaykum\"?", "bn": "\"আসসালামু আলাইকুম\"-এর জবাব কী?"}', '{"options": [{"en": "Wa alaykum as-salam", "bn": "ওয়া আলাইকুমুস সালাম"}, {"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "Insha’Allah", "bn": "ইনশাআল্লাহ"}, {"en": "Ameen", "bn": "আমিন"}], "correct": 0}', '{"en": "\"…greet with better than it or return it.\"", "bn": "\"…তার চেয়ে উত্তম সালাম দাও অথবা অন্তত তা ফিরিয়ে দাও।\""}', 'Quran 4:86', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f55a9858-218a-5b8b-9426-7c87686db51b', 'e81d5a55-b62b-53d6-b5e4-23fa3fee9725', 'choice', '{"en": "With which hand should we eat and drink?", "bn": "কোন হাতে খাওয়া-পান করা উচিত?"}', '{"options": [{"en": "Right hand", "bn": "ডান হাতে"}, {"en": "Left hand", "bn": "বাম হাতে"}, {"en": "Either", "bn": "যেকোনো হাতে"}, {"en": "Both", "bn": "দুই হাতে"}], "correct": 0}', '{"en": "\"When one of you eats, let him eat with his right hand.\"", "bn": "\"তোমাদের কেউ খেলে যেন ডান হাতে খায়।\""}', 'Sahih Muslim 2020', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9c0342b1-31a0-5f25-9799-17bc58a0305b', 'e81d5a55-b62b-53d6-b5e4-23fa3fee9725', 'choice', '{"en": "What should you say after sneezing?", "bn": "হাঁচি দেওয়ার পর কী বলা উচিত?"}', '{"options": [{"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "SubhanAllah", "bn": "সুবহানাল্লাহ"}, {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Astaghfirullah", "bn": "আস্তাগফিরুল্লাহ"}], "correct": 0}', '{"en": "The one who sneezes says \"Alhamdulillah\".", "bn": "যে হাঁচি দেয় সে বলবে \"আলহামদুলিল্লাহ\"।"}', 'Sahih al-Bukhari 6224', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('edc94db5-003d-5c28-83d6-ee6a71c06461', 'e81d5a55-b62b-53d6-b5e4-23fa3fee9725', 'choice', '{"en": "What do you say to someone who sneezes and says Alhamdulillah?", "bn": "কেউ হাঁচি দিয়ে আলহামদুলিল্লাহ বললে তাকে কী বলবেন?"}', '{"options": [{"en": "Yarhamuk-Allah", "bn": "ইয়ারহামুকাল্লাহ"}, {"en": "Ameen", "bn": "আমিন"}, {"en": "Masha’Allah", "bn": "মাশাআল্লাহ"}, {"en": "Bismillah", "bn": "বিসমিল্লাহ"}], "correct": 0}', '{"en": "\"May Allah have mercy on you.\"", "bn": "\"আল্লাহ তোমার প্রতি রহম করুন।\""}', 'Sahih al-Bukhari 6224', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('99667e1c-b956-5e75-bf2d-07b188961695', 'd33aef5f-06cd-5bc9-afc7-859ddef5d55e', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('581671c2-d210-528c-9951-f62edd769afc', '99667e1c-b956-5e75-bf2d-07b188961695', 'choice', '{"en": "Smiling at your brother is…?", "bn": "ভাইয়ের দিকে মুচকি হাসা হলো…?"}', '{"options": [{"en": "A charity (sadaqah)", "bn": "সদকা"}, {"en": "Disliked", "bn": "অপছন্দনীয়"}, {"en": "Only for children", "bn": "শুধু শিশুদের জন্য"}, {"en": "Wasting time", "bn": "সময় নষ্ট"}], "correct": 0}', '{"en": "\"Your smile in the face of your brother is charity.\"", "bn": "\"তোমার ভাইয়ের সামনে তোমার হাসি সদকা।\""}', 'Jami‘ at-Tirmidhi 1956', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3a17d075-1f90-571c-babc-22bfaabe122c', '99667e1c-b956-5e75-bf2d-07b188961695', 'choice', '{"en": "Complete: \"None of you truly believes until he loves for his brother what he…\"", "bn": "পূর্ণ করুন: \"তোমাদের কেউ পূর্ণ মুমিন হবে না, যতক্ষণ না সে তার ভাইয়ের জন্য তা পছন্দ করে যা সে…\""}', '{"options": [{"en": "…loves for himself", "bn": "…নিজের জন্য পছন্দ করে"}, {"en": "…owns", "bn": "…মালিক"}, {"en": "…fears", "bn": "…ভয় করে"}, {"en": "…eats", "bn": "…খায়"}], "correct": 0}', '{"en": "Wanting good for others as for yourself is part of faith.", "bn": "নিজের মতো অন্যের জন্য কল্যাণ চাওয়া ঈমানের অংশ।"}', 'Sahih al-Bukhari 13', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('01db9098-96e4-51fa-9f0a-92cb73f4ebd3', '99667e1c-b956-5e75-bf2d-07b188961695', 'choice', '{"en": "Who are the best of you, according to the hadith?", "bn": "হাদিস অনুযায়ী তোমাদের মধ্যে শ্রেষ্ঠ কে?"}', '{"options": [{"en": "The richest", "bn": "সবচেয়ে ধনী"}, {"en": "Those who learn the Quran and teach it", "bn": "যে কুরআন শেখে ও শেখায়"}, {"en": "The strongest", "bn": "সবচেয়ে শক্তিশালী"}, {"en": "The oldest", "bn": "সবচেয়ে বয়স্ক"}], "correct": 1}', '{"en": "\"The best of you are those who learn the Quran and teach it.\"", "bn": "\"তোমাদের মধ্যে সর্বোত্তম সে, যে কুরআন শেখে ও শেখায়।\""}', 'Sahih al-Bukhari 5027', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('63cc6a18-887e-5cca-b1d3-6c9c3897029b', '99667e1c-b956-5e75-bf2d-07b188961695', 'choice', '{"en": "What should a Muslim say before starting something good?", "bn": "ভালো কাজ শুরুর আগে মুসলমান কী বলবে?"}', '{"options": [{"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Ameen", "bn": "আমিন"}, {"en": "Wa alaykum", "bn": "ওয়া আলাইকুম"}, {"en": "Ma‘as-salamah", "bn": "মাআস সালামা"}], "correct": 0}', '{"en": "\"In the name of Allah\", as before eating, wudu and leaving home.", "bn": "\"আল্লাহর নামে\", যেমন খাওয়া, অজু ও ঘর থেকে বের হওয়ার আগে।"}', 'Sunan Abi Dawud 3767', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5509694b-b126-5799-a416-4cde031ca9fd', '99667e1c-b956-5e75-bf2d-07b188961695', 'choice', '{"en": "Who has the greatest right to your good company?", "bn": "তোমার সদাচরণ পাওয়ার সবচেয়ে বেশি হকদার কে?"}', '{"options": [{"en": "Your friend", "bn": "তোমার বন্ধু"}, {"en": "Your mother", "bn": "তোমার মা"}, {"en": "Your teacher", "bn": "তোমার শিক্ষক"}, {"en": "Your neighbour", "bn": "তোমার প্রতিবেশী"}], "correct": 1}', '{"en": "\"Your mother, then your mother, then your mother, then your father.\"", "bn": "\"তোমার মা, তারপর তোমার মা, তারপর তোমার মা, তারপর তোমার বাবা।\""}', 'Sahih al-Bukhari 5971', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('dfb94559-119f-596c-b17f-0ff0b26396fb', 'd33aef5f-06cd-5bc9-afc7-859ddef5d55e', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
