INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('8c222283-f19c-5083-8150-08768aace36c', '0429dcbd-ee46-5093-bc7c-210d968535c1', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('05771a70-6049-5c0f-80ca-776028abe69f', '8c222283-f19c-5083-8150-08768aace36c', 'choice', '{"en": "Paradise lies at the feet of…?", "bn": "জান্নাত কার পায়ের নিচে?"}', '{"options": [{"en": "Mothers", "bn": "মায়েদের"}, {"en": "Kings", "bn": "রাজাদের"}, {"en": "Teachers", "bn": "শিক্ষকদের"}, {"en": "Soldiers", "bn": "সৈনিকদের"}], "correct": 0}', '{"en": "\"Stay with her (your mother), for Paradise is at her feet.\"", "bn": "\"তার (মায়ের) সেবায় থাকো, কারণ জান্নাত তার পায়ের নিচে।\""}', 'Sunan an-Nasa’i 3104', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('446af13f-c915-53ff-a543-d2bb71ad8f32', '8c222283-f19c-5083-8150-08768aace36c', 'choice', '{"en": "Jibril kept advising the Prophet ﷺ about whom, until he thought they would inherit?", "bn": "জিবরাইল নবীজিকে ﷺ কার ব্যাপারে এত উপদেশ দিতেন যে তিনি ভাবলেন সে উত্তরাধিকারী হবে?"}', '{"options": [{"en": "The neighbour", "bn": "প্রতিবেশী"}, {"en": "The traveller", "bn": "মুসাফির"}, {"en": "The king", "bn": "রাজা"}, {"en": "The merchant", "bn": "ব্যবসায়ী"}], "correct": 0}', '{"en": "The rights of neighbours are great in Islam.", "bn": "ইসলামে প্রতিবেশীর হক অনেক বড়।"}', 'Sahih al-Bukhari 6014', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('904abe8d-36d5-5cac-b60a-e71a2efbb3a0', '8c222283-f19c-5083-8150-08768aace36c', 'choice', '{"en": "Truthfulness leads to righteousness, and righteousness leads to…?", "bn": "সত্যবাদিতা নেকির দিকে নিয়ে যায়, আর নেকি নিয়ে যায়…?"}', '{"options": [{"en": "Paradise", "bn": "জান্নাতে"}, {"en": "Wealth", "bn": "সম্পদে"}, {"en": "Fame", "bn": "খ্যাতিতে"}, {"en": "Power", "bn": "ক্ষমতায়"}], "correct": 0}', '{"en": "\"Truthfulness leads to righteousness, and righteousness leads to Paradise.\"", "bn": "\"সত্য নেকির পথ দেখায়, আর নেকি জান্নাতের পথ দেখায়।\""}', 'Sahih al-Bukhari 6094', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fe85b142-0712-512f-94d7-0811f2003b0a', '8c222283-f19c-5083-8150-08768aace36c', 'choice', '{"en": "What must we never say to our parents, even when they are old?", "bn": "বাবা-মা বৃদ্ধ হলেও তাদের কী বলা যাবে না?"}', '{"options": [{"en": "\"Uff\" (a word of annoyance)", "bn": "\"উফ\" (বিরক্তির শব্দ)"}, {"en": "Thank you", "bn": "ধন্যবাদ"}, {"en": "As-salamu alaykum", "bn": "আসসালামু আলাইকুম"}, {"en": "May Allah have mercy on you", "bn": "আল্লাহ রহম করুন"}], "correct": 0}', '{"en": "\"…do not say to them uff, nor repel them, but speak to them a noble word.\"", "bn": "\"…তাদের উফ বোলো না, ধমক দিয়ো না, বরং সম্মানের সাথে কথা বলো।\""}', 'Quran 17:23', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a7874e35-276c-598f-87b8-4dd3bbe8252b', '8c222283-f19c-5083-8150-08768aace36c', 'choice', '{"en": "Who is truly strong, according to the hadith?", "bn": "হাদিস অনুযায়ী প্রকৃত শক্তিশালী কে?"}', '{"options": [{"en": "One who controls himself when angry", "bn": "যে রাগের সময় নিজেকে নিয়ন্ত্রণ করে"}, {"en": "One who wins every fight", "bn": "যে সব লড়াইয়ে জেতে"}, {"en": "One who lifts heavy weights", "bn": "যে ভারী বোঝা তোলে"}, {"en": "One who shouts loudly", "bn": "যে জোরে চিৎকার করে"}], "correct": 0}', '{"en": "\"The strong one is not the good wrestler; the strong one controls himself when angry.\"", "bn": "\"কুস্তিতে জয়ী শক্তিশালী নয়; শক্তিশালী সে, যে রাগের সময় নিজেকে নিয়ন্ত্রণ করে।\""}', 'Sahih al-Bukhari 6114', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d2069bca-41a9-5a2b-b5b0-8140a50df771', '0429dcbd-ee46-5093-bc7c-210d968535c1', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9ed9b710-27dc-5323-b7d9-0dc0ff63133f', 'd2069bca-41a9-5a2b-b5b0-8140a50df771', 'choice', '{"en": "Keeping ties with relatives increases…?", "bn": "আত্মীয়তার সম্পর্ক রক্ষা করলে কী বাড়ে?"}', '{"options": [{"en": "Provision and lifespan", "bn": "রিজিক ও আয়ু"}, {"en": "Worries", "bn": "দুশ্চিন্তা"}, {"en": "Debts", "bn": "ঋণ"}, {"en": "Enemies", "bn": "শত্রু"}], "correct": 0}', '{"en": "\"Whoever wishes for more provision and a longer life, let him keep ties of kinship.\"", "bn": "\"যে রিজিক ও আয়ু বৃদ্ধি চায়, সে যেন আত্মীয়তার সম্পর্ক রক্ষা করে।\""}', 'Sahih al-Bukhari 5986', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a28f6976-b2ad-53cd-8057-10f20ec4eca5', 'd2069bca-41a9-5a2b-b5b0-8140a50df771', 'choice', '{"en": "The best of you, said the Prophet ﷺ, are those who are best to…?", "bn": "নবী ﷺ বলেছেন, তোমাদের মধ্যে উত্তম সে, যে সবচেয়ে উত্তম…?"}', '{"options": [{"en": "Their families", "bn": "নিজ পরিবারের কাছে"}, {"en": "Their bosses", "bn": "নিজ কর্তার কাছে"}, {"en": "Strangers only", "bn": "শুধু অপরিচিতদের কাছে"}, {"en": "Themselves", "bn": "নিজের কাছে"}], "correct": 0}', '{"en": "\"…and I am the best of you to my family.\"", "bn": "\"…আর আমি আমার পরিবারের কাছে তোমাদের মধ্যে সর্বোত্তম।\""}', 'Jami‘ at-Tirmidhi 3895', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('015bbdc7-543a-58bb-9d40-b8f145033105', 'd2069bca-41a9-5a2b-b5b0-8140a50df771', 'choice', '{"en": "The Quran likens backbiting to…?", "bn": "কুরআন গিবতকে কীসের সাথে তুলনা করেছে?"}', '{"options": [{"en": "Eating your dead brother’s flesh", "bn": "মৃত ভাইয়ের গোশত খাওয়া"}, {"en": "Drinking water", "bn": "পানি পান"}, {"en": "Walking fast", "bn": "দ্রুত হাঁটা"}, {"en": "Sleeping late", "bn": "দেরিতে ঘুমানো"}], "correct": 0}', '{"en": "\"…would one of you like to eat the flesh of his dead brother? You would detest it.\"", "bn": "\"…তোমাদের কেউ কি মৃত ভাইয়ের গোশত খেতে পছন্দ করবে? তোমরা তো তা ঘৃণা করো।\""}', 'Quran 49:12', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('50d0da76-340a-50c3-8b46-09eb2866b6fd', 'd2069bca-41a9-5a2b-b5b0-8140a50df771', 'choice', '{"en": "The one who looks after an orphan will be with the Prophet ﷺ in Paradise like…?", "bn": "এতিমের দায়িত্ব যে নেয়, জান্নাতে নবীজির ﷺ সাথে থাকবে যেভাবে…?"}', '{"options": [{"en": "Two fingers side by side", "bn": "পাশাপাশি দুই আঙুল"}, {"en": "Two far cities", "bn": "দূরের দুই শহর"}, {"en": "A king and a servant", "bn": "রাজা ও সেবক"}, {"en": "Two mountains", "bn": "দুই পাহাড়"}], "correct": 0}', '{"en": "He ﷺ held up his index and middle fingers together.", "bn": "তিনি ﷺ তর্জনী ও মধ্যমা একসাথে দেখালেন।"}', 'Sahih al-Bukhari 5304', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('873cac9a-ddd4-5f36-9da6-3cabb82362a7', 'd2069bca-41a9-5a2b-b5b0-8140a50df771', 'choice', '{"en": "Modesty (haya’) brings nothing but…?", "bn": "লজ্জাশীলতা (হায়া) কী ছাড়া কিছুই আনে না?"}', '{"options": [{"en": "Good", "bn": "কল্যাণ"}, {"en": "Loss", "bn": "ক্ষতি"}, {"en": "Sadness", "bn": "দুঃখ"}, {"en": "Trouble", "bn": "ঝামেলা"}], "correct": 0}', '{"en": "\"Modesty brings nothing except good.\"", "bn": "\"লজ্জা কল্যাণ ছাড়া কিছুই আনে না।\""}', 'Sahih al-Bukhari 6117', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a7713413-9060-590b-bd78-2daec71fb9d7', '0429dcbd-ee46-5093-bc7c-210d968535c1', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
