INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('33fd638d-2f5f-52f4-acbf-a6851baab111', 'a7713413-9060-590b-bd78-2daec71fb9d7', 'choice', '{"en": "Modesty (haya’) brings nothing but…?", "bn": "লজ্জাশীলতা (হায়া) কী ছাড়া কিছুই আনে না?"}', '{"options": [{"en": "Good", "bn": "কল্যাণ"}, {"en": "Loss", "bn": "ক্ষতি"}, {"en": "Sadness", "bn": "দুঃখ"}, {"en": "Trouble", "bn": "ঝামেলা"}], "correct": 0}', '{"en": "\"Modesty brings nothing except good.\"", "bn": "\"লজ্জা কল্যাণ ছাড়া কিছুই আনে না।\""}', 'Sahih al-Bukhari 6117', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4583b885-8b4d-50be-b204-632e59eb1f85', 'a7713413-9060-590b-bd78-2daec71fb9d7', 'choice', '{"en": "Paradise lies at the feet of…?", "bn": "জান্নাত কার পায়ের নিচে?"}', '{"options": [{"en": "Mothers", "bn": "মায়েদের"}, {"en": "Kings", "bn": "রাজাদের"}, {"en": "Teachers", "bn": "শিক্ষকদের"}, {"en": "Soldiers", "bn": "সৈনিকদের"}], "correct": 0}', '{"en": "\"Stay with her (your mother), for Paradise is at her feet.\"", "bn": "\"তার (মায়ের) সেবায় থাকো, কারণ জান্নাত তার পায়ের নিচে।\""}', 'Sunan an-Nasa’i 3104', 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('71810a0e-e946-5ad5-a081-4d2bbe8899cc', '{"en": "Sunnah in daily life", "bn": "দৈনন্দিন জীবনে সুন্নাহ"}', '{}', '#00a8ff', 'hand-heart', 'in_review', 3, '5a7e3402-fa72-5037-89ea-f4b0391c6f62') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('1736f05f-01fe-5000-92f5-44a947b85def', '71810a0e-e946-5ad5-a081-4d2bbe8899cc', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('295462c2-76fb-50e3-a882-fc8e8eda80d5', '1736f05f-01fe-5000-92f5-44a947b85def', 'choice', '{"en": "What is the twig used to clean the teeth called?", "bn": "দাঁত পরিষ্কারের ডালকে কী বলে?"}', '{"options": [{"en": "Siwak (miswak)", "bn": "মিসওয়াক"}, {"en": "Tasbih", "bn": "তাসবিহ"}, {"en": "Kohl", "bn": "সুরমা"}, {"en": "Henna", "bn": "মেহেদি"}], "correct": 0}', '{"en": "\"Were it not hard on my ummah, I would have ordered them to use the siwak for every prayer.\"", "bn": "\"আমার উম্মতের জন্য কষ্টকর না হলে আমি প্রতি নামাজের জন্য মিসওয়াকের নির্দেশ দিতাম।\""}', 'Sahih al-Bukhari 887', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('74a1a7c3-a857-56d8-9a29-0a7d7ed03271', '1736f05f-01fe-5000-92f5-44a947b85def', 'choice', '{"en": "On which side is it sunnah to lie down to sleep?", "bn": "কোন কাতে শোয়া সুন্নাত?"}', '{"options": [{"en": "The right side", "bn": "ডান কাতে"}, {"en": "The left side", "bn": "বাম কাতে"}, {"en": "On the stomach", "bn": "উপুড় হয়ে"}, {"en": "Sitting up", "bn": "বসে"}], "correct": 0}', '{"en": "\"…then lie down on your right side.\"", "bn": "\"…তারপর ডান কাতে শোও।\""}', 'Sahih al-Bukhari 247', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d0c22b0b-0946-54b3-84c7-b2ac9b9b23be', '1736f05f-01fe-5000-92f5-44a947b85def', 'choice', '{"en": "Mentioning Allah when entering home and eating keeps away…?", "bn": "ঘরে প্রবেশ ও খাওয়ার সময় আল্লাহর নাম নিলে কে দূরে থাকে?"}', '{"options": [{"en": "Shaytan", "bn": "শয়তান"}, {"en": "Guests", "bn": "মেহমান"}, {"en": "Neighbours", "bn": "প্রতিবেশী"}, {"en": "Children", "bn": "শিশুরা"}], "correct": 0}', '{"en": "Shaytan says: you have no place to stay and no dinner.", "bn": "শয়তান বলে: তোমাদের থাকার জায়গা নেই, রাতের খাবারও নেই।"}', 'Sahih Muslim 2018', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3c1da3f9-f41e-5347-91c7-4c6238e3846f', '1736f05f-01fe-5000-92f5-44a947b85def', 'choice', '{"en": "How did the Prophet ﷺ prefer to drink?", "bn": "নবী ﷺ কীভাবে পান করতে পছন্দ করতেন?"}', '{"options": [{"en": "Sitting", "bn": "বসে"}, {"en": "Running", "bn": "দৌড়ে"}, {"en": "Lying down", "bn": "শুয়ে"}, {"en": "In one gulp", "bn": "এক চুমুকে"}], "correct": 0}', '{"en": "He ﷺ discouraged drinking while standing.", "bn": "তিনি ﷺ দাঁড়িয়ে পান করতে নিরুৎসাহিত করেছেন।"}', 'Sahih Muslim 2024', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e047b77f-07a5-5110-a725-75ea532f063c', '1736f05f-01fe-5000-92f5-44a947b85def', 'choice', '{"en": "Visiting a sick Muslim is like being in…?", "bn": "অসুস্থ মুসলিমকে দেখতে যাওয়া যেন…?"}', '{"options": [{"en": "The harvest of Paradise", "bn": "জান্নাতের ফল আহরণে থাকা"}, {"en": "A market", "bn": "বাজারে থাকা"}, {"en": "A long journey", "bn": "দীর্ঘ সফরে থাকা"}, {"en": "A school", "bn": "স্কুলে থাকা"}], "correct": 0}', '{"en": "\"…he remains in the harvest of Paradise until he returns.\"", "bn": "\"…সে ফিরে আসা পর্যন্ত জান্নাতের ফল আহরণে থাকে।\""}', 'Sahih Muslim 2568', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('1bf1ca6b-e6b5-5710-8c54-037e9040ed86', '71810a0e-e946-5ad5-a081-4d2bbe8899cc', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('19c8d8a7-6629-55e2-97d0-c067a386ecdc', '1bf1ca6b-e6b5-5710-8c54-037e9040ed86', 'choice', '{"en": "Removing something harmful from the road is…?", "bn": "রাস্তা থেকে কষ্টদায়ক জিনিস সরানো হলো…?"}', '{"options": [{"en": "A branch of iman", "bn": "ঈমানের একটি শাখা"}, {"en": "Not our job", "bn": "আমাদের কাজ না"}, {"en": "Disliked", "bn": "অপছন্দনীয়"}, {"en": "Only for workers", "bn": "শুধু শ্রমিকদের কাজ"}], "correct": 0}', '{"en": "\"…and the lowest of them is removing harm from the road.\"", "bn": "\"…আর এর সর্বনিম্ন শাখা রাস্তা থেকে কষ্টদায়ক জিনিস সরানো।\""}', 'Sahih Muslim 35', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e044e69d-9af1-5b94-991b-15bfc6d4bb6e', '1bf1ca6b-e6b5-5710-8c54-037e9040ed86', 'choice', '{"en": "Putting on shoes, the sunnah is to start with…?", "bn": "জুতা পরার সময় কোন পা দিয়ে শুরু করা সুন্নাত?"}', '{"options": [{"en": "The right foot", "bn": "ডান পা"}, {"en": "The left foot", "bn": "বাম পা"}, {"en": "Either", "bn": "যেকোনো"}, {"en": "Both at once", "bn": "দুটো একসাথে"}], "correct": 0}', '{"en": "\"…begin with the right, and when removing, begin with the left.\"", "bn": "\"…ডান দিয়ে শুরু করো, আর খোলার সময় বাম দিয়ে।\""}', 'Sahih al-Bukhari 5855', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5026b576-e485-55a6-bfc0-cbabd59c4ddf', '1bf1ca6b-e6b5-5710-8c54-037e9040ed86', 'choice', '{"en": "What do we say before entering the toilet?", "bn": "টয়লেটে ঢোকার আগে কী বলি?"}', '{"options": [{"en": "Allahumma inni a‘udhu bika minal-khubuthi wal-khaba’ith", "bn": "আল্লাহুম্মা ইন্নি আউযু বিকা মিনাল খুবুসি ওয়াল খাবায়িস"}, {"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "Ameen", "bn": "আমিন"}, {"en": "Nothing", "bn": "কিছু না"}], "correct": 0}', '{"en": "\"O Allah, I seek refuge in You from the male and female devils.\"", "bn": "\"হে আল্লাহ, আমি পুরুষ ও নারী শয়তান থেকে আপনার আশ্রয় চাই।\""}', 'Sahih al-Bukhari 142', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0025dfd8-b7ac-5ba5-91c7-75e9e280be48', '1bf1ca6b-e6b5-5710-8c54-037e9040ed86', 'choice', '{"en": "When yawning, we should…?", "bn": "হাই তোলার সময় আমাদের উচিত…?"}', '{"options": [{"en": "Cover the mouth", "bn": "মুখ ঢেকে রাখা"}, {"en": "Say Alhamdulillah", "bn": "আলহামদুলিল্লাহ বলা"}, {"en": "Laugh", "bn": "হাসা"}, {"en": "Clap", "bn": "হাততালি দেওয়া"}], "correct": 0}', '{"en": "\"…let him put his hand over his mouth.\"", "bn": "\"…সে যেন মুখে হাত রাখে।\""}', 'Sahih Muslim 2995', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d2b27ab0-9ab0-5baa-9279-5ca831e56190', '1bf1ca6b-e6b5-5710-8c54-037e9040ed86', 'choice', '{"en": "What is said at the start of wudu?", "bn": "অজুর শুরুতে কী বলা হয়?"}', '{"options": [{"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Allahu Akbar", "bn": "আল্লাহু আকবার"}, {"en": "Ameen", "bn": "আমিন"}, {"en": "Astaghfirullah", "bn": "আস্তাগফিরুল্লাহ"}], "correct": 0}', '{"en": "Begin wudu in the name of Allah.", "bn": "আল্লাহর নামে অজু শুরু করো।"}', 'Sunan Abi Dawud 101', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('51c90207-ce42-50a9-8661-02cfa170f9a7', '71810a0e-e946-5ad5-a081-4d2bbe8899cc', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
