INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b0c0e1d7-ddf3-5c47-9144-975814d6d4a1', '51c90207-ce42-50a9-8661-02cfa170f9a7', 'choice', '{"en": "What is the twig used to clean the teeth called?", "bn": "দাঁত পরিষ্কারের ডালকে কী বলে?"}', '{"options": [{"en": "Siwak (miswak)", "bn": "মিসওয়াক"}, {"en": "Tasbih", "bn": "তাসবিহ"}, {"en": "Kohl", "bn": "সুরমা"}, {"en": "Henna", "bn": "মেহেদি"}], "correct": 0}', '{"en": "\"Were it not hard on my ummah, I would have ordered them to use the siwak for every prayer.\"", "bn": "\"আমার উম্মতের জন্য কষ্টকর না হলে আমি প্রতি নামাজের জন্য মিসওয়াকের নির্দেশ দিতাম।\""}', 'Sahih al-Bukhari 887', 6) ON CONFLICT (id) DO NOTHING;
