INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('cb52e993-9659-51c9-9e30-74cf2307b146', 'd68eaede-ac11-525d-8e3b-be2f6c5d2548', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3a97c5ac-6095-5595-b543-f8e4dfc5ef6b', 'cb52e993-9659-51c9-9e30-74cf2307b146', 'choice', '{"en": "What is the best dhikr, according to the hadith?", "bn": "হাদিস অনুযায়ী সর্বোত্তম যিকির কোনটি?"}', '{"options": [{"en": "La ilaha illallah", "bn": "লা ইলাহা ইল্লাল্লাহ"}, {"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Ameen", "bn": "আমিন"}, {"en": "Insha’Allah", "bn": "ইনশাআল্লাহ"}], "correct": 0}', '{"en": "\"The best dhikr is La ilaha illallah.\"", "bn": "\"সর্বোত্তম যিকির লা ইলাহা ইল্লাল্লাহ।\""}', 'Jami‘ at-Tirmidhi 3383', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('de3a31af-196c-5e06-b33b-d7617904c27c', 'cb52e993-9659-51c9-9e30-74cf2307b146', 'choice', '{"en": "Which two phrases are light on the tongue and heavy on the Scale?", "bn": "কোন দুটি বাক্য জিহ্বায় হালকা আর মিজানে ভারী?"}', '{"options": [{"en": "SubhanAllahi wa bihamdihi, SubhanAllahil-‘Azim", "bn": "সুবহানাল্লাহি ওয়া বিহামদিহি, সুবহানাল্লাহিল আযিম"}, {"en": "Bismillah, Alhamdulillah", "bn": "বিসমিল্লাহ, আলহামদুলিল্লাহ"}, {"en": "Ameen, Ameen", "bn": "আমিন, আমিন"}, {"en": "Allahu Akbar, Allahu Akbar", "bn": "আল্লাহু আকবার, আল্লাহু আকবার"}], "correct": 0}', '{"en": "\"…beloved to the Most Merciful.\"", "bn": "\"…দয়াময়ের কাছে প্রিয়।\""}', 'Sahih al-Bukhari 6406', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4ca09c1d-a6cf-55ea-b08a-47e9adb4eda2', 'cb52e993-9659-51c9-9e30-74cf2307b146', 'choice', '{"en": "Which words are \"a treasure of Paradise\"?", "bn": "কোন বাক্য \"জান্নাতের ধনভাণ্ডার\"?"}', '{"options": [{"en": "La hawla wa la quwwata illa billah", "bn": "লা হাওলা ওয়ালা কুওয়াতা ইল্লা বিল্লাহ"}, {"en": "Astaghfirullah", "bn": "আস্তাগফিরুল্লাহ"}, {"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "Masha’Allah", "bn": "মাশাআল্লাহ"}], "correct": 0}', '{"en": "\"There is no might nor power except with Allah.\"", "bn": "\"আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই।\""}', 'Sahih al-Bukhari 6384', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e9dffce6-75fa-5354-b68b-56e8c755aa8f', 'cb52e993-9659-51c9-9e30-74cf2307b146', 'choice', '{"en": "What is the \"master of seeking forgiveness\" called?", "bn": "\"ক্ষমা চাওয়ার সর্দার\" দোয়াকে কী বলে?"}', '{"options": [{"en": "Sayyid al-Istighfar", "bn": "সাইয়্যিদুল ইস্তিগফার"}, {"en": "Ayat al-Kursi", "bn": "আয়াতুল কুরসি"}, {"en": "Du‘a al-Qunut", "bn": "দোয়া কুনুত"}, {"en": "Talbiyah", "bn": "তালবিয়া"}], "correct": 0}', '{"en": "\"O Allah, You are my Lord, there is no god but You…\"", "bn": "\"হে আল্লাহ, আপনি আমার রব, আপনি ছাড়া কোনো উপাস্য নেই…\""}', 'Sahih al-Bukhari 6306', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5cbc6417-a527-5e0d-8c44-4eeda17884b4', 'cb52e993-9659-51c9-9e30-74cf2307b146', 'choice', '{"en": "After the adhan, the Prophet ﷺ taught us to ask Allah to grant him…?", "bn": "আজানের পর নবী ﷺ আমাদের শিখিয়েছেন তাঁর জন্য আল্লাহর কাছে কী চাইতে?"}', '{"options": [{"en": "Al-Wasilah", "bn": "আল-ওয়াসিলা"}, {"en": "Wealth", "bn": "সম্পদ"}, {"en": "A long life", "bn": "দীর্ঘায়ু"}, {"en": "A house", "bn": "একটি ঘর"}], "correct": 0}', '{"en": "\"…then ask Allah to grant me al-Wasilah, a rank in Paradise.\"", "bn": "\"…তারপর আমার জন্য আল্লাহর কাছে ওয়াসিলা চাও, যা জান্নাতের একটি মর্যাদা।\""}', 'Sahih Muslim 384', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('e0e2903c-916a-5e9d-ac9c-d2dfa8933b5c', 'd68eaede-ac11-525d-8e3b-be2f6c5d2548', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3d369acb-5025-5474-b4fa-8d20177ae709', 'e0e2903c-916a-5e9d-ac9c-d2dfa8933b5c', 'choice', '{"en": "Reciting Ayat al-Kursi before sleeping keeps you protected until…?", "bn": "ঘুমানোর আগে আয়াতুল কুরসি পড়লে কখন পর্যন্ত সুরক্ষিত থাকবেন?"}', '{"options": [{"en": "Morning", "bn": "সকাল"}, {"en": "Noon", "bn": "দুপুর"}, {"en": "Friday", "bn": "শুক্রবার"}, {"en": "One week", "bn": "এক সপ্তাহ"}], "correct": 0}', '{"en": "A guardian from Allah stays with you and no devil comes near until morning.", "bn": "আল্লাহর পক্ষ থেকে একজন রক্ষাকারী থাকে এবং সকাল পর্যন্ত শয়তান কাছে আসে না।"}', 'Sahih al-Bukhari 2311', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('99412ef0-b6d8-5e18-a1c0-772bbbf5e3c9', 'e0e2903c-916a-5e9d-ac9c-d2dfa8933b5c', 'choice', '{"en": "Which two surahs are the best for seeking refuge?", "bn": "আশ্রয় চাওয়ার জন্য কোন দুটি সূরা সর্বোত্তম?"}', '{"options": [{"en": "Al-Falaq and An-Nas", "bn": "আল-ফালাক ও আন-নাস"}, {"en": "Al-Fatiha and Al-Baqarah", "bn": "আল-ফাতিহা ও আল-বাকারা"}, {"en": "Ya-Sin and Ar-Rahman", "bn": "ইয়াসিন ও আর-রহমান"}, {"en": "Al-Mulk and Al-Kahf", "bn": "আল-মুলক ও আল-কাহফ"}], "correct": 0}', '{"en": "\"Have you not seen ayahs revealed tonight, the like of which were never seen: al-Falaq and an-Nas.\"", "bn": "\"তুমি কি দেখোনি আজ রাতে এমন আয়াত নাজিল হয়েছে, যার মতো কখনো দেখা যায়নি: আল-ফালাক ও আন-নাস।\""}', 'Sahih Muslim 814', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f2bd96c7-21b6-56e4-a33e-1fc465df4ca2', 'e0e2903c-916a-5e9d-ac9c-d2dfa8933b5c', 'choice', '{"en": "The dua of Yunus begins with…?", "bn": "ইউনুস (আ.)-এর দোয়া শুরু হয়…?"}', '{"options": [{"en": "La ilaha illa anta, subhanaka", "bn": "লা ইলাহা ইল্লা আনতা, সুবহানাকা"}, {"en": "Rabbana atina", "bn": "রব্বানা আতিনা"}, {"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Allahumma barik", "bn": "আল্লাহুম্মা বারিক"}], "correct": 0}', '{"en": "\"…I have indeed been among the wrongdoers.\"", "bn": "\"…নিশ্চয়ই আমি জালিমদের অন্তর্ভুক্ত ছিলাম।\""}', 'Quran 21:87', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b252cc38-f6d0-55be-9591-bab71e513687', 'e0e2903c-916a-5e9d-ac9c-d2dfa8933b5c', 'choice', '{"en": "Dua between the adhan and the iqamah is…?", "bn": "আজান ও ইকামতের মাঝের দোয়া…?"}', '{"options": [{"en": "Not rejected", "bn": "ফিরিয়ে দেওয়া হয় না"}, {"en": "Forbidden", "bn": "নিষিদ্ধ"}, {"en": "Disliked", "bn": "অপছন্দনীয়"}, {"en": "Only for imams", "bn": "শুধু ইমামের জন্য"}], "correct": 0}', '{"en": "\"Dua between the adhan and the iqamah is not rejected.\"", "bn": "\"আজান ও ইকামতের মাঝের দোয়া ফিরিয়ে দেওয়া হয় না।\""}', 'Jami‘ at-Tirmidhi 212', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e95c8d7c-17ad-58f0-88aa-baa1c2bc7f90', 'e0e2903c-916a-5e9d-ac9c-d2dfa8933b5c', 'choice', '{"en": "What should you say when leaving home?", "bn": "ঘর থেকে বের হওয়ার সময় কী বলবেন?"}', '{"options": [{"en": "Bismillah, tawakkaltu ‘alallah…", "bn": "বিসমিল্লাহি, তাওয়াক্কালতু আলাল্লাহ…"}, {"en": "Alhamdulillah only", "bn": "শুধু আলহামদুলিল্লাহ"}, {"en": "Nothing", "bn": "কিছু না"}, {"en": "Ameen", "bn": "আমিন"}], "correct": 0}', '{"en": "\"…there is no might nor power except with Allah.\" It is said to him: you are guided, sufficed and protected.", "bn": "\"…আল্লাহ ছাড়া কোনো শক্তি ও সামর্থ্য নেই।\" তাকে বলা হয়: তুমি হেদায়াত পেলে, যথেষ্ট হলে ও রক্ষা পেলে।"}', 'Sunan Abi Dawud 5095', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('b16407ed-d8a9-5eac-9476-4626ce9da178', 'd68eaede-ac11-525d-8e3b-be2f6c5d2548', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
