INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4dabe51f-df28-52aa-8f76-05bfe876981d', '715aa695-d8f5-5543-92b2-040c95c1a681', 'choice', '{"en": "What does \"Insha’Allah\" mean?", "bn": "\"ইনশাআল্লাহ\" অর্থ কী?"}', '{"options": [{"en": "If Allah wills", "bn": "আল্লাহ চাইলে"}, {"en": "Thank you", "bn": "ধন্যবাদ"}, {"en": "Goodbye", "bn": "বিদায়"}, {"en": "Well done", "bn": "বাহ"}], "correct": 0}', '{"en": "\"And never say of anything, I will do it tomorrow, except (adding) if Allah wills.\"", "bn": "\"কোনো বিষয়ে বোলো না যে আমি আগামীকাল এটা করব, তবে আল্লাহ চাইলে (বলে)।\""}', 'Quran 18:23–24', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('155e0755-b7ea-5aa0-906d-3c670fb1cbaa', '715aa695-d8f5-5543-92b2-040c95c1a681', 'choice', '{"en": "What does \"Masha’Allah\" mean?", "bn": "\"মাশাআল্লাহ\" অর্থ কী?"}', '{"options": [{"en": "What Allah has willed", "bn": "আল্লাহ যা চেয়েছেন"}, {"en": "Sorry", "bn": "দুঃখিত"}, {"en": "Hurry up", "bn": "তাড়াতাড়ি"}, {"en": "Peace", "bn": "শান্তি"}], "correct": 0}', '{"en": "Said when admiring something: \"What Allah willed; there is no power except with Allah.\"", "bn": "কিছু দেখে মুগ্ধ হলে: \"আল্লাহ যা চেয়েছেন; আল্লাহ ছাড়া কোনো শক্তি নেই।\""}', 'Quran 18:39', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d9e8f5b7-6b30-5167-9126-e059b482891e', '715aa695-d8f5-5543-92b2-040c95c1a681', 'choice', '{"en": "What does \"SubhanAllah\" mean?", "bn": "\"সুবহানাল্লাহ\" অর্থ কী?"}', '{"options": [{"en": "Glory be to Allah", "bn": "আল্লাহ পবিত্র"}, {"en": "Allah is great", "bn": "আল্লাহ মহান"}, {"en": "Praise be to Allah", "bn": "সব প্রশংসা আল্লাহর"}, {"en": "I seek forgiveness", "bn": "ক্ষমা চাই"}], "correct": 0}', '{"en": "It declares Allah free of every imperfection.", "bn": "এটি ঘোষণা করে যে আল্লাহ সব ত্রুটি থেকে মুক্ত।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2979d86f-36ca-514e-bfad-f879dd9de9c7', '715aa695-d8f5-5543-92b2-040c95c1a681', 'choice', '{"en": "What does \"JazakAllahu khayran\" mean?", "bn": "\"জাযাকাল্লাহু খাইরান\" অর্থ কী?"}', '{"options": [{"en": "May Allah reward you with good", "bn": "আল্লাহ আপনাকে উত্তম প্রতিদান দিন"}, {"en": "Good night", "bn": "শুভ রাত্রি"}, {"en": "Excuse me", "bn": "মাফ করবেন"}, {"en": "Welcome", "bn": "স্বাগতম"}], "correct": 0}', '{"en": "\"Whoever is done a favour and says JazakAllahu khayran has praised well.\"", "bn": "\"যার উপকার করা হয় এবং সে বলে জাযাকাল্লাহু খাইরান, সে যথাযথ প্রশংসা করল।\""}', 'Jami‘ at-Tirmidhi 2035', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a911fbcd-1902-5799-b489-235804a666bc', '715aa695-d8f5-5543-92b2-040c95c1a681', 'choice', '{"en": "What does \"Astaghfirullah\" mean?", "bn": "\"আস্তাগফিরুল্লাহ\" অর্থ কী?"}', '{"options": [{"en": "I seek Allah’s forgiveness", "bn": "আমি আল্লাহর কাছে ক্ষমা চাই"}, {"en": "I trust Allah", "bn": "আমি আল্লাহর ওপর ভরসা করি"}, {"en": "Allah is One", "bn": "আল্লাহ এক"}, {"en": "Thank Allah", "bn": "আল্লাহর শুকরিয়া"}], "correct": 0}', '{"en": "The Prophet ﷺ sought forgiveness more than seventy times a day.", "bn": "নবী ﷺ দিনে সত্তরবারের বেশি ইস্তিগফার করতেন।"}', 'Sahih al-Bukhari 6307', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('eba639bc-8227-588a-97e0-da2a8c1f816d', 'a66762e7-49dc-5f55-8cfa-9b18c17f12f1', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d91149a9-bf5b-5440-9509-dd5b0ba3fd1a', 'eba639bc-8227-588a-97e0-da2a8c1f816d', 'choice', '{"en": "When do we say \"Inna lillahi wa inna ilayhi raji‘un\"?", "bn": "\"ইন্না লিল্লাহি ওয়া ইন্না ইলাইহি রাজিউন\" কখন বলি?"}', '{"options": [{"en": "When a calamity or death happens", "bn": "বিপদ বা মৃত্যুর সময়"}, {"en": "Before eating", "bn": "খাওয়ার আগে"}, {"en": "When sneezing", "bn": "হাঁচির সময়"}, {"en": "When greeting", "bn": "সালামের সময়"}], "correct": 0}', '{"en": "\"…who, when disaster strikes them, say: Indeed we belong to Allah and to Him we return.\"", "bn": "\"…যারা বিপদে পড়লে বলে: আমরা আল্লাহরই এবং তাঁর দিকেই ফিরে যাব।\""}', 'Quran 2:156', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e4fccd42-908d-5753-a092-3f3454998784', 'eba639bc-8227-588a-97e0-da2a8c1f816d', 'choice', '{"en": "What does \"Allahu Akbar\" mean?", "bn": "\"আল্লাহু আকবার\" অর্থ কী?"}', '{"options": [{"en": "Allah is the Greatest", "bn": "আল্লাহ সর্বশ্রেষ্ঠ"}, {"en": "Allah is One", "bn": "আল্লাহ এক"}, {"en": "Allah forgives", "bn": "আল্লাহ ক্ষমা করেন"}, {"en": "Allah knows", "bn": "আল্লাহ জানেন"}], "correct": 0}', '{"en": "Said in every salah and the adhan.", "bn": "প্রতি নামাজ ও আজানে বলা হয়।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8fe4c64e-3640-563c-8d70-06467cf0749f', 'eba639bc-8227-588a-97e0-da2a8c1f816d', 'choice', '{"en": "What does \"Ameen\" mean?", "bn": "\"আমিন\" অর্থ কী?"}', '{"options": [{"en": "O Allah, answer (our prayer)", "bn": "হে আল্লাহ, কবুল করুন"}, {"en": "Goodbye", "bn": "বিদায়"}, {"en": "Hello", "bn": "হ্যালো"}, {"en": "Well done", "bn": "বাহ"}], "correct": 0}', '{"en": "Said after al-Fatiha and after a dua.", "bn": "সূরা ফাতিহা ও দোয়ার পরে বলা হয়।"}', 'Sahih al-Bukhari 780', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('32ec989e-d749-52d9-ae47-058c00cee0b2', 'eba639bc-8227-588a-97e0-da2a8c1f816d', 'choice', '{"en": "What does \"Barakallahu fik\" mean?", "bn": "\"বারাকাল্লাহু ফিক\" অর্থ কী?"}', '{"options": [{"en": "May Allah bless you", "bn": "আল্লাহ আপনাকে বরকত দিন"}, {"en": "Be quiet", "bn": "চুপ থাকুন"}, {"en": "Come here", "bn": "এদিকে আসুন"}, {"en": "See you", "bn": "দেখা হবে"}], "correct": 0}', '{"en": "A dua for blessing, e.g. on a marriage.", "bn": "বরকতের দোয়া, যেমন বিয়েতে।"}', 'Sunan Abi Dawud 2130', 4) ON CONFLICT (id) DO NOTHING;
