INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e1570fbb-178b-5e0b-9fd9-639ed50ee3bd', '875240c3-01cc-53af-b32c-0c1750b755f1', 'choice', '{"en": "What is the first month of the Hijri year?", "bn": "হিজরি বছরের প্রথম মাস কোনটি?"}', '{"options": [{"en": "Muharram", "bn": "মহররম"}, {"en": "Ramadan", "bn": "রমজান"}, {"en": "Safar", "bn": "সফর"}, {"en": "Rajab", "bn": "রজব"}], "correct": 0}', '{"en": "The year begins with Muharram.", "bn": "বছর শুরু হয় মহররম দিয়ে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5aaa7392-3549-5ea5-aa48-c29aeadc03cb', '875240c3-01cc-53af-b32c-0c1750b755f1', 'choice', '{"en": "Ramadan is which month of the Hijri year?", "bn": "রমজান হিজরি বছরের কততম মাস?"}', '{"options": [{"en": "7th", "bn": "৭ম"}, {"en": "8th", "bn": "৮ম"}, {"en": "9th", "bn": "৯ম"}, {"en": "12th", "bn": "১২তম"}], "correct": 2}', '{"en": "Ramadan is the ninth month.", "bn": "রমজান নবম মাস।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4e8e0098-dcc2-5a1c-bfa6-04b268cfd855', '875240c3-01cc-53af-b32c-0c1750b755f1', 'choice', '{"en": "How many sacred months are there?", "bn": "হারাম (সম্মানিত) মাস কয়টি?"}', '{"options": [{"en": "2", "bn": "২"}, {"en": "3", "bn": "৩"}, {"en": "4", "bn": "৪"}, {"en": "12", "bn": "১২"}], "correct": 2}', '{"en": "\"…twelve months… of these, four are sacred.\"", "bn": "\"…বারো মাস… তার মধ্যে চারটি সম্মানিত।\""}', 'Quran 9:36', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a848f43d-a009-5933-9b89-4fbf70e6c0bc', '875240c3-01cc-53af-b32c-0c1750b755f1', 'choice', '{"en": "Which is the best day of the week?", "bn": "সপ্তাহের শ্রেষ্ঠ দিন কোনটি?"}', '{"options": [{"en": "Monday", "bn": "সোমবার"}, {"en": "Friday", "bn": "শুক্রবার"}, {"en": "Saturday", "bn": "শনিবার"}, {"en": "Thursday", "bn": "বৃহস্পতিবার"}], "correct": 1}', '{"en": "\"The best day on which the sun rises is Friday.\"", "bn": "\"যেসব দিনে সূর্য ওঠে তার শ্রেষ্ঠ দিন শুক্রবার।\""}', 'Sahih Muslim 854', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7b059b0e-01c7-5fb0-bf9f-113e6655a20c', '875240c3-01cc-53af-b32c-0c1750b755f1', 'choice', '{"en": "On which date is the Day of Arafah?", "bn": "আরাফার দিন কোন তারিখে?"}', '{"options": [{"en": "1 Dhul Hijjah", "bn": "১ জিলহজ"}, {"en": "9 Dhul Hijjah", "bn": "৯ জিলহজ"}, {"en": "10 Muharram", "bn": "১০ মহররম"}, {"en": "27 Ramadan", "bn": "২৭ রমজান"}], "correct": 1}', '{"en": "The 9th of Dhul Hijjah; Eid al-Adha is the next day.", "bn": "৯ জিলহজ; পরদিন ঈদুল আযহা।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
