INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2aa75e38-0044-55b7-ae99-dd937f9becd6', '381b0c93-a66f-51f5-8c18-5beb212675bc', 'choice', '{"en": "Eid al-Fitr falls on…?", "bn": "ঈদুল ফিতর কোন তারিখে?"}', '{"options": [{"en": "1 Shawwal", "bn": "১ শাওয়াল"}, {"en": "10 Dhul Hijjah", "bn": "১০ জিলহজ"}, {"en": "1 Muharram", "bn": "১ মহররম"}, {"en": "15 Sha‘ban", "bn": "১৫ শাবান"}], "correct": 0}', '{"en": "The first day of Shawwal, right after Ramadan.", "bn": "রমজানের পরপর, শাওয়ালের প্রথম দিন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0601a96e-d3c3-588d-8587-0ae11ab5114c', '381b0c93-a66f-51f5-8c18-5beb212675bc', 'choice', '{"en": "When does a new Hijri day begin?", "bn": "নতুন হিজরি দিন কখন শুরু হয়?"}', '{"options": [{"en": "At midnight", "bn": "মধ্যরাতে"}, {"en": "At sunrise", "bn": "সূর্যোদয়ে"}, {"en": "At sunset", "bn": "সূর্যাস্তে"}, {"en": "At noon", "bn": "দুপুরে"}], "correct": 2}', '{"en": "The lunar day starts at Maghrib; e.g. a night of Ramadan comes before its day.", "bn": "চান্দ্র দিন মাগরিবে শুরু হয়; যেমন রমজানের রাত তার দিনের আগে আসে।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3e52a97c-20c3-5e77-842d-bf9934ac4d68', '381b0c93-a66f-51f5-8c18-5beb212675bc', 'choice', '{"en": "On which weekdays did the Prophet ﷺ like to fast?", "bn": "নবী ﷺ সপ্তাহের কোন দিনগুলোতে রোজা রাখতে পছন্দ করতেন?"}', '{"options": [{"en": "Monday and Thursday", "bn": "সোম ও বৃহস্পতিবার"}, {"en": "Friday and Saturday", "bn": "শুক্র ও শনিবার"}, {"en": "Sunday and Tuesday", "bn": "রবি ও মঙ্গলবার"}, {"en": "Every day", "bn": "প্রতিদিন"}], "correct": 0}', '{"en": "\"Deeds are presented on Monday and Thursday, and I like my deeds presented while I am fasting.\"", "bn": "\"সোম ও বৃহস্পতিবার আমল পেশ করা হয়; আমি চাই রোজা অবস্থায় আমার আমল পেশ হোক।\""}', 'Jami‘ at-Tirmidhi 747', 3) ON CONFLICT (id) DO NOTHING;
