INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('98030e86-b3d9-5f75-9c29-39f96487ce8e', '381b0c93-a66f-51f5-8c18-5beb212675bc', 'choice', '{"en": "How many months are in the Islamic year?", "bn": "হিজরি বছরে কয়টি মাস?"}', '{"options": [{"en": "10", "bn": "১০"}, {"en": "12", "bn": "১২"}, {"en": "13", "bn": "১৩"}, {"en": "11", "bn": "১১"}], "correct": 1}', '{"en": "\"The number of months with Allah is twelve.\"", "bn": "\"আল্লাহর কাছে মাসের সংখ্যা বারো।\""}', 'Quran 9:36', 5) ON CONFLICT (id) DO NOTHING;
