INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3710fa46-b106-50a5-9281-ec1dd5eb6793', '1e73ce49-2d75-5513-b054-909e6593cbad', 'choice', '{"en": "Who was the first caliph after the Prophet ﷺ?", "bn": "নবী ﷺ-এর পর প্রথম খলিফা কে?"}', '{"options": [{"en": "‘Umar", "bn": "উমর"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Uthman", "bn": "উসমান"}, {"en": "‘Ali", "bn": "আলী"}], "correct": 1}', '{"en": "Abu Bakr as-Siddiq.", "bn": "আবু বকর সিদ্দিক (রা.)।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('22dc384f-adcd-52a6-9b5d-88af5be6ad8f', '1e73ce49-2d75-5513-b054-909e6593cbad', 'choice', '{"en": "Who was the second caliph?", "bn": "দ্বিতীয় খলিফা কে?"}', '{"options": [{"en": "‘Umar ibn al-Khattab", "bn": "উমর ইবনুল খাত্তাব"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Mu‘awiyah", "bn": "মুয়াবিয়া"}, {"en": "‘Uthman", "bn": "উসমান"}], "correct": 0}', '{"en": "‘Umar ibn al-Khattab.", "bn": "উমর ইবনুল খাত্তাব (রা.)।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d5464298-33fe-5cfa-a1d3-3cac90cc817b', '1e73ce49-2d75-5513-b054-909e6593cbad', 'choice', '{"en": "The Islamic (Hijri) calendar counts its years from which event?", "bn": "হিজরি সন কোন ঘটনা থেকে গণনা শুরু হয়?"}', '{"options": [{"en": "The Prophet’s birth", "bn": "নবীজির জন্ম"}, {"en": "The first revelation", "bn": "প্রথম ওহি"}, {"en": "The Hijrah to Madinah", "bn": "মদিনায় হিজরত"}, {"en": "The conquest of Makkah", "bn": "মক্কা বিজয়"}], "correct": 2}', '{"en": "Year 1 AH is the year of the Hijrah.", "bn": "হিজরতের বছরই হিজরি ১ সন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8f93f33f-2095-5540-9497-4b25dd582738', '1e73ce49-2d75-5513-b054-909e6593cbad', 'choice', '{"en": "Before the Ka‘bah, Muslims prayed towards…?", "bn": "কাবার আগে মুসলমানরা কোন দিকে নামাজ পড়তেন?"}', '{"options": [{"en": "Bayt al-Maqdis (Jerusalem)", "bn": "বায়তুল মাকদিস (জেরুজালেম)"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Yemen", "bn": "ইয়েমেন"}], "correct": 0}', '{"en": "The qiblah was changed from Bayt al-Maqdis to the Ka‘bah.", "bn": "কিবলা বায়তুল মাকদিস থেকে কাবার দিকে পরিবর্তন করা হয়।"}', 'Quran 2:142–144; Sahih al-Bukhari 40', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9fe0f228-bb15-52f5-960f-9b16730e918c', '1e73ce49-2d75-5513-b054-909e6593cbad', 'choice', '{"en": "Which caliph sent standard copies of the Quran to the major cities?", "bn": "কোন খলিফা কুরআনের প্রমিত কপি প্রধান শহরগুলোতে পাঠিয়েছিলেন?"}', '{"options": [{"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Uthman", "bn": "উসমান"}, {"en": "‘Umar", "bn": "উমর"}, {"en": "‘Ali", "bn": "আলী"}], "correct": 1}', '{"en": "‘Uthman had copies made and sent to each region.", "bn": "উসমান (রা.) কপি তৈরি করে প্রতিটি অঞ্চলে পাঠান।"}', 'Sahih al-Bukhari 4987', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d5e174ee-c72a-59f1-8160-eb95c0d08b11', 'a0ae7b01-f672-52eb-8348-de3ca8c9ef41', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('393cbbdc-6ea4-5f21-bac2-b3de3fdd2898', 'd5e174ee-c72a-59f1-8160-eb95c0d08b11', 'choice', '{"en": "Masjid al-Aqsa is in which city?", "bn": "মসজিদুল আকসা কোন শহরে?"}', '{"options": [{"en": "Damascus", "bn": "দামেস্ক"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "Cairo", "bn": "কায়রো"}, {"en": "Baghdad", "bn": "বাগদাদ"}], "correct": 1}', '{"en": "Al-Aqsa is in Jerusalem (al-Quds).", "bn": "আল-আকসা জেরুজালেমে (আল-কুদস)।"}', 'Quran 17:1', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3ec8d06c-1c80-532d-a165-0a5cc32c3504', 'd5e174ee-c72a-59f1-8160-eb95c0d08b11', 'choice', '{"en": "What is the night journey from Makkah to Jerusalem and the ascent called?", "bn": "মক্কা থেকে জেরুজালেম রাতের সফর ও ঊর্ধ্বগমনকে কী বলে?"}', '{"options": [{"en": "Hijrah", "bn": "হিজরত"}, {"en": "Isra and Mi‘raj", "bn": "ইসরা ও মিরাজ"}, {"en": "Badr", "bn": "বদর"}, {"en": "Hudaybiyyah", "bn": "হুদাইবিয়া"}], "correct": 1}', '{"en": "\"Glory be to Him who took His servant by night…\"", "bn": "\"পবিত্র তিনি, যিনি তাঁর বান্দাকে রাতে ভ্রমণ করিয়েছেন…\""}', 'Quran 17:1', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8e7ddb0f-e33b-570e-8dc7-528b662836b8', 'd5e174ee-c72a-59f1-8160-eb95c0d08b11', 'choice', '{"en": "The well of Zamzam is in…?", "bn": "যমযম কূপ কোথায়?"}', '{"options": [{"en": "Madinah", "bn": "মদিনা"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "Ta’if", "bn": "তায়েফ"}], "correct": 1}', '{"en": "Zamzam is inside al-Masjid al-Haram in Makkah.", "bn": "যমযম মক্কার মসজিদুল হারামের ভেতরে।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f5fd3719-de72-52d6-9d31-f3deb03b28ec', 'd5e174ee-c72a-59f1-8160-eb95c0d08b11', 'choice', '{"en": "Hajj takes place in which Hijri month?", "bn": "কোন হিজরি মাসে হজ হয়?"}', '{"options": [{"en": "Ramadan", "bn": "রমজান"}, {"en": "Muharram", "bn": "মহররম"}, {"en": "Dhul Hijjah", "bn": "জিলহজ"}, {"en": "Rajab", "bn": "রজব"}], "correct": 2}', '{"en": "The days of Hajj are 8–13 Dhul Hijjah.", "bn": "হজের দিন ৮–১৩ জিলহজ।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7f0f9b68-0519-541f-9d00-ba54c4b4bb40', 'd5e174ee-c72a-59f1-8160-eb95c0d08b11', 'choice', '{"en": "Who compiled the hadith book \"Sahih al-Bukhari\"?", "bn": "\"সহিহ বুখারি\" কে সংকলন করেন?"}', '{"options": [{"en": "Imam Muslim", "bn": "ইমাম মুসলিম"}, {"en": "Imam al-Bukhari", "bn": "ইমাম বুখারি"}, {"en": "Imam Malik", "bn": "ইমাম মালিক"}, {"en": "Imam Ahmad", "bn": "ইমাম আহমাদ"}], "correct": 1}', '{"en": "Muhammad ibn Isma‘il al-Bukhari.", "bn": "মুহাম্মাদ ইবনে ইসমাইল আল-বুখারি।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('7289fd1b-5f83-521f-8a87-96fe9118a6a6', 'a0ae7b01-f672-52eb-8348-de3ca8c9ef41', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
