INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('39af063e-b3dc-5cc2-a934-88546ea707fd', '7289fd1b-5f83-521f-8a87-96fe9118a6a6', 'choice', '{"en": "Before the Ka‘bah, Muslims prayed towards…?", "bn": "কাবার আগে মুসলমানরা কোন দিকে নামাজ পড়তেন?"}', '{"options": [{"en": "Bayt al-Maqdis (Jerusalem)", "bn": "বায়তুল মাকদিস (জেরুজালেম)"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Yemen", "bn": "ইয়েমেন"}], "correct": 0}', '{"en": "The qiblah was changed from Bayt al-Maqdis to the Ka‘bah.", "bn": "কিবলা বায়তুল মাকদিস থেকে কাবার দিকে পরিবর্তন করা হয়।"}', 'Quran 2:142–144; Sahih al-Bukhari 40', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('79e8ed82-80a1-50e1-9593-75e0556846b9', '7289fd1b-5f83-521f-8a87-96fe9118a6a6', 'choice', '{"en": "Masjid al-Aqsa is in which city?", "bn": "মসজিদুল আকসা কোন শহরে?"}', '{"options": [{"en": "Damascus", "bn": "দামেস্ক"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "Cairo", "bn": "কায়রো"}, {"en": "Baghdad", "bn": "বাগদাদ"}], "correct": 1}', '{"en": "Al-Aqsa is in Jerusalem (al-Quds).", "bn": "আল-আকসা জেরুজালেমে (আল-কুদস)।"}', 'Quran 17:1', 3) ON CONFLICT (id) DO NOTHING;
