INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ec82ce2e-9686-5856-923a-ddb5adc1ec07', '7289fd1b-5f83-521f-8a87-96fe9118a6a6', 'choice', '{"en": "Who was the first caliph after the Prophet ﷺ?", "bn": "নবী ﷺ-এর পর প্রথম খলিফা কে?"}', '{"options": [{"en": "‘Umar", "bn": "উমর"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Uthman", "bn": "উসমান"}, {"en": "‘Ali", "bn": "আলী"}], "correct": 1}', '{"en": "Abu Bakr as-Siddiq.", "bn": "আবু বকর সিদ্দিক (রা.)।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
