INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('76ff8b0d-3095-523a-bdba-010a25705548', '377db67d-6b79-5985-9bf3-c7d155596c02', 'choice', '{"en": "Who was known as \"as-Siddiq\"?", "bn": "কে \"সিদ্দিক\" উপাধিতে পরিচিত?"}', '{"options": [{"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Umar", "bn": "উমর"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Bilal", "bn": "বিলাল"}], "correct": 0}', '{"en": "Abu Bakr affirmed the Prophet ﷺ without hesitation, including the Night Journey.", "bn": "আবু বকর (রা.) দ্বিধাহীনভাবে নবীজিকে ﷺ সত্যায়ন করতেন, ইসরার ঘটনাসহ।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fb9faa49-72b7-51a3-b986-7d0ede4e29a0', '377db67d-6b79-5985-9bf3-c7d155596c02', 'choice', '{"en": "Who was known as \"al-Faruq\"?", "bn": "কে \"ফারুক\" উপাধিতে পরিচিত?"}', '{"options": [{"en": "‘Uthman", "bn": "উসমান"}, {"en": "‘Umar", "bn": "উমর"}, {"en": "Khalid", "bn": "খালিদ"}, {"en": "Sa‘d", "bn": "সাদ"}], "correct": 1}', '{"en": "‘Umar ibn al-Khattab, \"the one who distinguishes truth from falsehood\".", "bn": "উমর ইবনুল খাত্তাব (রা.), \"সত্য-মিথ্যার পার্থক্যকারী\"।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1cb42bac-8056-57cf-b2e0-02dbe55e528a', '377db67d-6b79-5985-9bf3-c7d155596c02', 'choice', '{"en": "Who was called \"Dhun-Nurayn\" (owner of two lights)?", "bn": "কাকে \"যুন-নুরাইন\" (দুই আলোর অধিকারী) বলা হয়?"}', '{"options": [{"en": "‘Uthman", "bn": "উসমান"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Talhah", "bn": "তালহা"}, {"en": "Zubayr", "bn": "যুবাইর"}], "correct": 0}', '{"en": "‘Uthman married two daughters of the Prophet ﷺ, Ruqayyah and then Umm Kulthum.", "bn": "উসমান (রা.) নবীজির ﷺ দুই কন্যা রুকাইয়া ও উম্মে কুলসুমকে বিয়ে করেছিলেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0b6264d3-5cea-5a7b-a559-0c8dbaf0ffdd', '377db67d-6b79-5985-9bf3-c7d155596c02', 'choice', '{"en": "Who was the mu’adhdhin of the Prophet ﷺ?", "bn": "নবীজির ﷺ মুয়াজ্জিন কে ছিলেন?"}', '{"options": [{"en": "Bilal ibn Rabah", "bn": "বিলাল ইবনে রাবাহ"}, {"en": "Abu Hurayrah", "bn": "আবু হুরায়রা"}, {"en": "Salman", "bn": "সালমান"}, {"en": "Anas", "bn": "আনাস"}], "correct": 0}', '{"en": "Bilal, who endured torture in Makkah saying \"Ahad, Ahad\".", "bn": "বিলাল (রা.), মক্কায় নির্যাতন সয়েও যিনি বলতেন \"আহাদ, আহাদ\"।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('eab18d77-c9e0-5dd8-b428-0680113907fe', '377db67d-6b79-5985-9bf3-c7d155596c02', 'choice', '{"en": "Who was called \"the Sword of Allah\"?", "bn": "কাকে \"আল্লাহর তরবারি\" বলা হয়?"}', '{"options": [{"en": "Hamzah", "bn": "হামজা"}, {"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ"}, {"en": "‘Amr ibn al-‘As", "bn": "আমর ইবনুল আস"}, {"en": "Mus‘ab", "bn": "মুসআব"}], "correct": 1}', '{"en": "The Prophet ﷺ called Khalid \"a sword from the swords of Allah\".", "bn": "নবী ﷺ খালিদকে \"আল্লাহর তরবারিসমূহের একটি\" বলেছেন।"}', 'Sahih al-Bukhari 3757', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('d3059514-9d6d-5fc8-984c-c01679691045', 'ce6a9bf1-3334-5e71-9298-0269790a0257', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dc84d20e-8300-5c48-9df5-48bba718d6db', 'd3059514-9d6d-5fc8-984c-c01679691045', 'choice', '{"en": "Which companion narrated the most hadith?", "bn": "কোন সাহাবি সবচেয়ে বেশি হাদিস বর্ণনা করেছেন?"}', '{"options": [{"en": "Abu Hurayrah", "bn": "আবু হুরায়রা"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "Mu‘adh", "bn": "মুআজ"}, {"en": "Zayd", "bn": "যায়েদ"}], "correct": 0}', '{"en": "Abu Hurayrah stayed close to the Prophet ﷺ to learn and memorise.", "bn": "আবু হুরায়রা (রা.) শেখা ও মুখস্থের জন্য নবীজির ﷺ কাছে থাকতেন।"}', 'Sahih al-Bukhari 118', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('923289fb-49d9-5157-9205-554aac953808', 'd3059514-9d6d-5fc8-984c-c01679691045', 'choice', '{"en": "Who was called \"the trustworthy one of this ummah\"?", "bn": "কাকে \"এই উম্মতের আমিন (বিশ্বস্ত)\" বলা হয়েছে?"}', '{"options": [{"en": "Abu ‘Ubaydah ibn al-Jarrah", "bn": "আবু উবাইদা ইবনুল জাররাহ"}, {"en": "Sa‘d ibn Abi Waqqas", "bn": "সাদ ইবনে আবি ওয়াক্কাস"}, {"en": "Ubayy ibn Ka‘b", "bn": "উবাই ইবনে কাব"}, {"en": "Abu Dharr", "bn": "আবু যর"}], "correct": 0}', '{"en": "\"Every nation has a trustworthy one, and ours is Abu ‘Ubaydah.\"", "bn": "\"প্রত্যেক উম্মতের একজন আমিন আছে, আমাদের আমিন আবু উবাইদা।\""}', 'Sahih al-Bukhari 3744', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6eab51bc-ba03-507d-bc95-1e792eebeb9a', 'd3059514-9d6d-5fc8-984c-c01679691045', 'choice', '{"en": "Who suggested digging the trench to defend Madinah?", "bn": "মদিনা রক্ষায় পরিখা খননের পরামর্শ কে দিয়েছিলেন?"}', '{"options": [{"en": "Salman al-Farisi", "bn": "সালমান ফারসি"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "Mu‘awiyah", "bn": "মুয়াবিয়া"}, {"en": "Ibn ‘Abbas", "bn": "ইবনে আব্বাস"}], "correct": 0}', '{"en": "Salman al-Farisi, from Persia, where trenches were used.", "bn": "পারস্যের সালমান ফারসি (রা.), যেখানে পরিখার প্রচলন ছিল।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b21244b6-8ec6-5d9b-ad0c-0b6969225b09', 'd3059514-9d6d-5fc8-984c-c01679691045', 'choice', '{"en": "Who was the fourth caliph?", "bn": "চতুর্থ খলিফা কে?"}', '{"options": [{"en": "‘Ali ibn Abi Talib", "bn": "আলী ইবনে আবি তালিব"}, {"en": "‘Uthman", "bn": "উসমান"}, {"en": "Hasan", "bn": "হাসান"}, {"en": "‘Umar ibn ‘Abd al-‘Aziz", "bn": "উমর ইবনে আবদুল আজিজ"}], "correct": 0}', '{"en": "After Abu Bakr, ‘Umar and ‘Uthman came ‘Ali.", "bn": "আবু বকর, উমর ও উসমানের পর আলী (রা.)।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5295cca4-3740-5b51-9206-4faf3a37d74a', 'd3059514-9d6d-5fc8-984c-c01679691045', 'choice', '{"en": "Which companion was the Prophet’s ﷺ uncle, \"the lion of Allah\", martyred at Uhud?", "bn": "নবীজির ﷺ কোন চাচা \"আল্লাহর সিংহ\", উহুদে শহিদ হন?"}', '{"options": [{"en": "Hamzah", "bn": "হামজা"}, {"en": "‘Abbas", "bn": "আব্বাস"}, {"en": "Abu Talib", "bn": "আবু তালিব"}, {"en": "Abu Lahab", "bn": "আবু লাহাব"}], "correct": 0}', '{"en": "Hamzah ibn ‘Abd al-Muttalib, martyred at Uhud.", "bn": "হামজা ইবনে আবদুল মুত্তালিব (রা.), উহুদে শহিদ।"}', 'Sahih al-Bukhari 4072', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('90d00906-9a29-5ae2-998b-cb3e27246893', 'ce6a9bf1-3334-5e71-9298-0269790a0257', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6427dc21-9dae-5a58-a371-5224ffcd98da', '90d00906-9a29-5ae2-998b-cb3e27246893', 'choice', '{"en": "Who was known as \"al-Faruq\"?", "bn": "কে \"ফারুক\" উপাধিতে পরিচিত?"}', '{"options": [{"en": "‘Uthman", "bn": "উসমান"}, {"en": "‘Umar", "bn": "উমর"}, {"en": "Khalid", "bn": "খালিদ"}, {"en": "Sa‘d", "bn": "সাদ"}], "correct": 1}', '{"en": "‘Umar ibn al-Khattab, \"the one who distinguishes truth from falsehood\".", "bn": "উমর ইবনুল খাত্তাব (রা.), \"সত্য-মিথ্যার পার্থক্যকারী\"।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1f0f5c39-a2e2-56df-aa08-7b5268c11ab9', '90d00906-9a29-5ae2-998b-cb3e27246893', 'choice', '{"en": "Who was the mu’adhdhin of the Prophet ﷺ?", "bn": "নবীজির ﷺ মুয়াজ্জিন কে ছিলেন?"}', '{"options": [{"en": "Bilal ibn Rabah", "bn": "বিলাল ইবনে রাবাহ"}, {"en": "Abu Hurayrah", "bn": "আবু হুরায়রা"}, {"en": "Salman", "bn": "সালমান"}, {"en": "Anas", "bn": "আনাস"}], "correct": 0}', '{"en": "Bilal, who endured torture in Makkah saying \"Ahad, Ahad\".", "bn": "বিলাল (রা.), মক্কায় নির্যাতন সয়েও যিনি বলতেন \"আহাদ, আহাদ\"।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1edc9c06-ea9f-5197-8cda-be325ea47234', '90d00906-9a29-5ae2-998b-cb3e27246893', 'choice', '{"en": "Which companion narrated the most hadith?", "bn": "কোন সাহাবি সবচেয়ে বেশি হাদিস বর্ণনা করেছেন?"}', '{"options": [{"en": "Abu Hurayrah", "bn": "আবু হুরায়রা"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "Mu‘adh", "bn": "মুআজ"}, {"en": "Zayd", "bn": "যায়েদ"}], "correct": 0}', '{"en": "Abu Hurayrah stayed close to the Prophet ﷺ to learn and memorise.", "bn": "আবু হুরায়রা (রা.) শেখা ও মুখস্থের জন্য নবীজির ﷺ কাছে থাকতেন।"}', 'Sahih al-Bukhari 118', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d3c3a5b0-7955-58ae-811e-2b5e9180171c', '90d00906-9a29-5ae2-998b-cb3e27246893', 'choice', '{"en": "Who suggested digging the trench to defend Madinah?", "bn": "মদিনা রক্ষায় পরিখা খননের পরামর্শ কে দিয়েছিলেন?"}', '{"options": [{"en": "Salman al-Farisi", "bn": "সালমান ফারসি"}, {"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "Mu‘awiyah", "bn": "মুয়াবিয়া"}, {"en": "Ibn ‘Abbas", "bn": "ইবনে আব্বাস"}], "correct": 0}', '{"en": "Salman al-Farisi, from Persia, where trenches were used.", "bn": "পারস্যের সালমান ফারসি (রা.), যেখানে পরিখার প্রচলন ছিল।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b0e29633-7387-5425-b935-61bfd1974a4a', '90d00906-9a29-5ae2-998b-cb3e27246893', 'choice', '{"en": "Which companion was the Prophet’s ﷺ uncle, \"the lion of Allah\", martyred at Uhud?", "bn": "নবীজির ﷺ কোন চাচা \"আল্লাহর সিংহ\", উহুদে শহিদ হন?"}', '{"options": [{"en": "Hamzah", "bn": "হামজা"}, {"en": "‘Abbas", "bn": "আব্বাস"}, {"en": "Abu Talib", "bn": "আবু তালিব"}, {"en": "Abu Lahab", "bn": "আবু লাহাব"}], "correct": 0}', '{"en": "Hamzah ibn ‘Abd al-Muttalib, martyred at Uhud.", "bn": "হামজা ইবনে আবদুল মুত্তালিব (রা.), উহুদে শহিদ।"}', 'Sahih al-Bukhari 4072', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e5e596a5-ad18-560e-adc6-6f470e8131e1', '90d00906-9a29-5ae2-998b-cb3e27246893', 'choice', '{"en": "Who was known as \"as-Siddiq\"?", "bn": "কে \"সিদ্দিক\" উপাধিতে পরিচিত?"}', '{"options": [{"en": "Abu Bakr", "bn": "আবু বকর"}, {"en": "‘Umar", "bn": "উমর"}, {"en": "‘Ali", "bn": "আলী"}, {"en": "Bilal", "bn": "বিলাল"}], "correct": 0}', '{"en": "Abu Bakr affirmed the Prophet ﷺ without hesitation, including the Night Journey.", "bn": "আবু বকর (রা.) দ্বিধাহীনভাবে নবীজিকে ﷺ সত্যায়ন করতেন, ইসরার ঘটনাসহ।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('fc263c50-ba38-534f-b4fa-bfe2721ab80f', '{"en": "Great women in Islamic history", "bn": "ইসলামের ইতিহাসে মহীয়সী নারী"}', '{}', '#9c88ff', 'library', 'in_review', 3, '5094d379-bb7c-5678-9866-1c62e0e88f45') ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('69dd3c9e-9736-5011-ae4e-60faec16e044', 'fc263c50-ba38-534f-b4fa-bfe2721ab80f', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('55d86ce0-ff9d-59ce-9d7b-f2dda2e77cd0', '69dd3c9e-9736-5011-ae4e-60faec16e044', 'choice', '{"en": "Who was the first person to accept Islam?", "bn": "সর্বপ্রথম কে ইসলাম গ্রহণ করেন?"}', '{"options": [{"en": "Khadijah", "bn": "খাদিজা"}, {"en": "‘A’ishah", "bn": "আয়েশা"}, {"en": "Fatimah", "bn": "ফাতিমা"}, {"en": "Sumayyah", "bn": "সুমাইয়া"}], "correct": 0}', '{"en": "Khadijah believed in him first and comforted him after the first revelation.", "bn": "খাদিজা (রা.) সবার আগে ঈমান আনেন এবং প্রথম ওহির পর নবীজিকে সান্ত্বনা দেন।"}', 'Sahih al-Bukhari 3', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cc5df3a8-ef90-5e98-8cc7-aaf3b19d46d4', '69dd3c9e-9736-5011-ae4e-60faec16e044', 'choice', '{"en": "Which daughter of the Prophet ﷺ married ‘Ali?", "bn": "নবীজির ﷺ কোন কন্যা আলী (রা.)-কে বিয়ে করেন?"}', '{"options": [{"en": "Zaynab", "bn": "যায়নাব"}, {"en": "Ruqayyah", "bn": "রুকাইয়া"}, {"en": "Fatimah", "bn": "ফাতিমা"}, {"en": "Umm Kulthum", "bn": "উম্মে কুলসুম"}], "correct": 2}', '{"en": "Fatimah, mother of al-Hasan and al-Husayn.", "bn": "ফাতিমা (রা.), হাসান ও হুসাইনের মা।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e1d0bd4d-65f4-5455-b781-2cfec264362c', '69dd3c9e-9736-5011-ae4e-60faec16e044', 'choice', '{"en": "Which woman is named in the Quran?", "bn": "কোন নারীর নাম কুরআনে আছে?"}', '{"options": [{"en": "Khadijah", "bn": "খাদিজা"}, {"en": "Maryam", "bn": "মারইয়াম"}, {"en": "Hajar", "bn": "হাজেরা"}, {"en": "Asiyah", "bn": "আসিয়া"}], "correct": 1}', '{"en": "Maryam is the only woman named in the Quran; a surah is named after her.", "bn": "মারইয়াম (আ.) কুরআনে নাম উল্লেখিত একমাত্র নারী; তাঁর নামে একটি সূরা আছে।"}', 'Quran 19', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cadc1efe-4dd6-59ce-a24f-0859243aea18', '69dd3c9e-9736-5011-ae4e-60faec16e044', 'choice', '{"en": "Whose wife believed in Allah and is praised in the Quran?", "bn": "কার স্ত্রী আল্লাহর প্রতি ঈমান আনেন এবং কুরআনে প্রশংসিত?"}', '{"options": [{"en": "Pharaoh’s", "bn": "ফেরাউনের"}, {"en": "Nuh’s", "bn": "নুহের"}, {"en": "Lut’s", "bn": "লুতের"}, {"en": "Abu Lahab’s", "bn": "আবু লাহাবের"}], "correct": 0}', '{"en": "\"…the wife of Pharaoh, when she said: My Lord, build for me a house near You in Paradise.\"", "bn": "\"…ফেরাউনের স্ত্রী, যখন সে বলল: হে আমার রব, আপনার কাছে জান্নাতে আমার জন্য একটি ঘর বানিয়ে দিন।\""}', 'Quran 66:11', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0fd76b52-af52-530a-948c-bda449cf43e7', '69dd3c9e-9736-5011-ae4e-60faec16e044', 'choice', '{"en": "Who ran between Safa and Marwah looking for water for her baby?", "bn": "শিশুর জন্য পানি খুঁজতে কে সাফা-মারওয়ার মাঝে দৌড়েছিলেন?"}', '{"options": [{"en": "Sarah", "bn": "সারা"}, {"en": "Hajar", "bn": "হাজেরা"}, {"en": "Maryam", "bn": "মারইয়াম"}, {"en": "Halimah", "bn": "হালিমা"}], "correct": 1}', '{"en": "Hajar, mother of Isma‘il; Zamzam then gushed forth.", "bn": "ইসমাইলের মা হাজেরা; এরপর যমযম প্রবাহিত হয়।"}', 'Sahih al-Bukhari 3364', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('ebc2f1a2-094f-5478-b470-f66a37562bba', 'fc263c50-ba38-534f-b4fa-bfe2721ab80f', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1b89b2af-ced8-5abb-97d1-e390e66d85bd', 'ebc2f1a2-094f-5478-b470-f66a37562bba', 'choice', '{"en": "Which wife of the Prophet ﷺ was known for her great knowledge?", "bn": "নবীজির ﷺ কোন স্ত্রী গভীর জ্ঞানের জন্য প্রসিদ্ধ?"}', '{"options": [{"en": "‘A’ishah", "bn": "আয়েশা"}, {"en": "Sawdah", "bn": "সাওদা"}, {"en": "Zaynab", "bn": "যায়নাব"}, {"en": "Maymunah", "bn": "মাইমুনা"}], "correct": 0}', '{"en": "‘A’ishah narrated many hadith and companions asked her about rulings.", "bn": "আয়েশা (রা.) অনেক হাদিস বর্ণনা করেছেন; সাহাবিরা তাঁর কাছে মাসআলা জিজ্ঞেস করতেন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2365b673-e7f7-5689-8294-d1b6baa9053b', 'ebc2f1a2-094f-5478-b470-f66a37562bba', 'choice', '{"en": "Who nursed the Prophet ﷺ as a baby in the desert?", "bn": "শৈশবে মরুভূমিতে কে নবীজিকে ﷺ দুধ পান করান?"}', '{"options": [{"en": "Halimah as-Sa‘diyyah", "bn": "হালিমা সাদিয়া"}, {"en": "Aminah", "bn": "আমিনা"}, {"en": "Barakah", "bn": "বারাকা"}, {"en": "Safiyyah", "bn": "সাফিয়া"}], "correct": 0}', '{"en": "Halimah of the Banu Sa‘d.", "bn": "বনু সাদ গোত্রের হালিমা।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('444693cd-fbf0-5254-86e2-e1448dcbb151', 'ebc2f1a2-094f-5478-b470-f66a37562bba', 'choice', '{"en": "Who is known as the first martyr in Islam?", "bn": "ইসলামের প্রথম শহিদ হিসেবে কে পরিচিত?"}', '{"options": [{"en": "Sumayyah", "bn": "সুমাইয়া"}, {"en": "Hamzah", "bn": "হামজা"}, {"en": "Mus‘ab", "bn": "মুসআব"}, {"en": "Ja‘far", "bn": "জাফর"}], "correct": 0}', '{"en": "Sumayyah, mother of ‘Ammar, killed in Makkah for her faith.", "bn": "আম্মারের মা সুমাইয়া (রা.), ঈমানের জন্য মক্কায় শহিদ হন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('90967381-3193-5166-a4f7-e35d143266c0', 'ebc2f1a2-094f-5478-b470-f66a37562bba', 'choice', '{"en": "Musa’s mother was inspired to put him in a box in…?", "bn": "মুসার মা কোথায় তাঁকে বাক্সে রাখার ইলহাম পেয়েছিলেন?"}', '{"options": [{"en": "A cave", "bn": "একটি গুহায়"}, {"en": "The river", "bn": "নদীতে"}, {"en": "A well", "bn": "একটি কূপে"}, {"en": "A palace", "bn": "একটি প্রাসাদে"}], "correct": 1}', '{"en": "\"…cast him into the river and do not fear.\"", "bn": "\"…তাকে নদীতে ফেলে দাও এবং ভয় কোরো না।\""}', 'Quran 28:7', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('385ede2c-4737-5a05-981c-4f951c7c2ecd', 'ebc2f1a2-094f-5478-b470-f66a37562bba', 'choice', '{"en": "Who are called \"Mothers of the Believers\"?", "bn": "\"উম্মাহাতুল মুমিনিন\" (মুমিনদের মা) কারা?"}', '{"options": [{"en": "All mothers", "bn": "সব মা"}, {"en": "The Prophet’s ﷺ wives", "bn": "নবীজির ﷺ স্ত্রীগণ"}, {"en": "The Prophet’s daughters", "bn": "নবীজির কন্যাগণ"}, {"en": "Women of Madinah", "bn": "মদিনার নারীরা"}], "correct": 1}', '{"en": "\"…and his wives are their mothers.\"", "bn": "\"…আর তাঁর স্ত্রীগণ তাদের মা।\""}', 'Quran 33:6', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('c91661fe-afc0-5875-8610-6a50cd47ec80', 'fc263c50-ba38-534f-b4fa-bfe2721ab80f', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ecdb914b-d548-5926-8bf3-f5f4aff86ca1', 'c91661fe-afc0-5875-8610-6a50cd47ec80', 'choice', '{"en": "Which daughter of the Prophet ﷺ married ‘Ali?", "bn": "নবীজির ﷺ কোন কন্যা আলী (রা.)-কে বিয়ে করেন?"}', '{"options": [{"en": "Zaynab", "bn": "যায়নাব"}, {"en": "Ruqayyah", "bn": "রুকাইয়া"}, {"en": "Fatimah", "bn": "ফাতিমা"}, {"en": "Umm Kulthum", "bn": "উম্মে কুলসুম"}], "correct": 2}', '{"en": "Fatimah, mother of al-Hasan and al-Husayn.", "bn": "ফাতিমা (রা.), হাসান ও হুসাইনের মা।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('df95b2ac-51c3-5e06-a6ff-47964d752e62', 'c91661fe-afc0-5875-8610-6a50cd47ec80', 'choice', '{"en": "Whose wife believed in Allah and is praised in the Quran?", "bn": "কার স্ত্রী আল্লাহর প্রতি ঈমান আনেন এবং কুরআনে প্রশংসিত?"}', '{"options": [{"en": "Pharaoh’s", "bn": "ফেরাউনের"}, {"en": "Nuh’s", "bn": "নুহের"}, {"en": "Lut’s", "bn": "লুতের"}, {"en": "Abu Lahab’s", "bn": "আবু লাহাবের"}], "correct": 0}', '{"en": "\"…the wife of Pharaoh, when she said: My Lord, build for me a house near You in Paradise.\"", "bn": "\"…ফেরাউনের স্ত্রী, যখন সে বলল: হে আমার রব, আপনার কাছে জান্নাতে আমার জন্য একটি ঘর বানিয়ে দিন।\""}', 'Quran 66:11', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6373f204-60dd-534b-abd3-9a7a1cbfa996', 'c91661fe-afc0-5875-8610-6a50cd47ec80', 'choice', '{"en": "Which wife of the Prophet ﷺ was known for her great knowledge?", "bn": "নবীজির ﷺ কোন স্ত্রী গভীর জ্ঞানের জন্য প্রসিদ্ধ?"}', '{"options": [{"en": "‘A’ishah", "bn": "আয়েশা"}, {"en": "Sawdah", "bn": "সাওদা"}, {"en": "Zaynab", "bn": "যায়নাব"}, {"en": "Maymunah", "bn": "মাইমুনা"}], "correct": 0}', '{"en": "‘A’ishah narrated many hadith and companions asked her about rulings.", "bn": "আয়েশা (রা.) অনেক হাদিস বর্ণনা করেছেন; সাহাবিরা তাঁর কাছে মাসআলা জিজ্ঞেস করতেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('4452798a-3adb-50f2-9b12-62f3fb387000', 'c91661fe-afc0-5875-8610-6a50cd47ec80', 'choice', '{"en": "Who is known as the first martyr in Islam?", "bn": "ইসলামের প্রথম শহিদ হিসেবে কে পরিচিত?"}', '{"options": [{"en": "Sumayyah", "bn": "সুমাইয়া"}, {"en": "Hamzah", "bn": "হামজা"}, {"en": "Mus‘ab", "bn": "মুসআব"}, {"en": "Ja‘far", "bn": "জাফর"}], "correct": 0}', '{"en": "Sumayyah, mother of ‘Ammar, killed in Makkah for her faith.", "bn": "আম্মারের মা সুমাইয়া (রা.), ঈমানের জন্য মক্কায় শহিদ হন।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7efbbb6d-119e-5ad7-9005-61bf477a8911', 'c91661fe-afc0-5875-8610-6a50cd47ec80', 'choice', '{"en": "Who are called \"Mothers of the Believers\"?", "bn": "\"উম্মাহাতুল মুমিনিন\" (মুমিনদের মা) কারা?"}', '{"options": [{"en": "All mothers", "bn": "সব মা"}, {"en": "The Prophet’s ﷺ wives", "bn": "নবীজির ﷺ স্ত্রীগণ"}, {"en": "The Prophet’s daughters", "bn": "নবীজির কন্যাগণ"}, {"en": "Women of Madinah", "bn": "মদিনার নারীরা"}], "correct": 1}', '{"en": "\"…and his wives are their mothers.\"", "bn": "\"…আর তাঁর স্ত্রীগণ তাদের মা।\""}', 'Quran 33:6', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9f8169a4-e491-5105-adc7-94ed763f41e0', 'c91661fe-afc0-5875-8610-6a50cd47ec80', 'choice', '{"en": "Who was the first person to accept Islam?", "bn": "সর্বপ্রথম কে ইসলাম গ্রহণ করেন?"}', '{"options": [{"en": "Khadijah", "bn": "খাদিজা"}, {"en": "‘A’ishah", "bn": "আয়েশা"}, {"en": "Fatimah", "bn": "ফাতিমা"}, {"en": "Sumayyah", "bn": "সুমাইয়া"}], "correct": 0}', '{"en": "Khadijah believed in him first and comforted him after the first revelation.", "bn": "খাদিজা (রা.) সবার আগে ঈমান আনেন এবং প্রথম ওহির পর নবীজিকে সান্ত্বনা দেন।"}', 'Sahih al-Bukhari 3', 6) ON CONFLICT (id) DO NOTHING;
