INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('1ae70d06-bfa9-5a00-8b01-e0060db55bff', '8002ceae-45f1-50d4-86c8-bfe3fb6da70e', '{"en": "Part 1", "bn": "পর্ব ১"}', 'lesson', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3ba145fc-2611-5b3c-9c96-986790753590', '1ae70d06-bfa9-5a00-8b01-e0060db55bff', 'choice', '{"en": "Masjid al-Haram is in…?", "bn": "মসজিদুল হারাম কোথায়?"}', '{"options": [{"en": "Makkah", "bn": "মক্কা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "Damascus", "bn": "দামেস্ক"}], "correct": 0}', '{"en": "It surrounds the Ka‘bah.", "bn": "এটি কাবাকে ঘিরে আছে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c2e3cf47-39f9-576c-8f83-f4f1c17a0a39', '1ae70d06-bfa9-5a00-8b01-e0060db55bff', 'choice', '{"en": "Masjid an-Nabawi (the Prophet’s Mosque) is in…?", "bn": "মসজিদে নববী কোথায়?"}', '{"options": [{"en": "Madinah", "bn": "মদিনা"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Jeddah", "bn": "জেদ্দা"}], "correct": 0}', '{"en": "He ﷺ built it after the Hijrah.", "bn": "হিজরতের পর তিনি ﷺ এটি নির্মাণ করেন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6c951eda-d322-5753-a282-e1afa50a2ed5', '1ae70d06-bfa9-5a00-8b01-e0060db55bff', 'choice', '{"en": "Which three mosques may one travel to for worship?", "bn": "ইবাদতের উদ্দেশ্যে কোন তিন মসজিদে সফর করা যায়?"}', '{"options": [{"en": "Al-Haram, an-Nabawi, al-Aqsa", "bn": "আল-হারাম, আন-নববী, আল-আকসা"}, {"en": "Quba, al-Haram, Uhud", "bn": "কুবা, আল-হারাম, উহুদ"}, {"en": "Any three", "bn": "যেকোনো তিনটি"}, {"en": "Only al-Haram", "bn": "শুধু আল-হারাম"}], "correct": 0}', '{"en": "\"Do not set out on a journey except to three mosques…\"", "bn": "\"তিনটি মসজিদ ছাড়া অন্য কোথাও (ইবাদতের উদ্দেশ্যে) সফর করো না…\""}', 'Sahih al-Bukhari 1189', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('49065d18-459d-5132-9119-b3c541dec78f', '1ae70d06-bfa9-5a00-8b01-e0060db55bff', 'choice', '{"en": "Which was the first mosque the Prophet ﷺ built?", "bn": "নবী ﷺ নির্মিত প্রথম মসজিদ কোনটি?"}', '{"options": [{"en": "Quba", "bn": "কুবা"}, {"en": "Al-Aqsa", "bn": "আল-আকসা"}, {"en": "Al-Haram", "bn": "আল-হারাম"}, {"en": "Al-Qiblatayn", "bn": "আল-কিবলাতাইন"}], "correct": 0}', '{"en": "Built at Quba on the way to Madinah, \"founded on taqwa\".", "bn": "মদিনার পথে কুবায় নির্মিত, \"তাকওয়ার ভিত্তিতে প্রতিষ্ঠিত\"।"}', 'Quran 9:108', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('edf274ab-6598-500c-ad99-2014e537a01a', '1ae70d06-bfa9-5a00-8b01-e0060db55bff', 'choice', '{"en": "The cave of Hira is on which mountain?", "bn": "হেরা গুহা কোন পাহাড়ে?"}', '{"options": [{"en": "Jabal an-Nur", "bn": "জাবালে নূর"}, {"en": "Uhud", "bn": "উহুদ"}, {"en": "Sinai", "bn": "সিনাই"}, {"en": "Thawr", "bn": "সাওর"}], "correct": 0}', '{"en": "Jabal an-Nur, \"the Mountain of Light\", near Makkah.", "bn": "মক্কার কাছে জাবালে নূর, \"আলোর পাহাড়\"।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('c3d46567-369f-5e81-aba2-9481af2582bf', '8002ceae-45f1-50d4-86c8-bfe3fb6da70e', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('107a2cc1-ecb2-5f51-b32b-19a724120420', 'c3d46567-369f-5e81-aba2-9481af2582bf', 'choice', '{"en": "Where do pilgrims stand on 9 Dhul Hijjah?", "bn": "৯ জিলহজ হাজিরা কোথায় অবস্থান করেন?"}', '{"options": [{"en": "Arafat", "bn": "আরাফাত"}, {"en": "Mina", "bn": "মিনা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Quba", "bn": "কুবা"}], "correct": 0}', '{"en": "The plain of Arafat.", "bn": "আরাফাতের ময়দান।"}', 'Quran 2:198', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('6271a5e8-41f6-5e43-8cd2-29f111ebea2e', 'c3d46567-369f-5e81-aba2-9481af2582bf', 'choice', '{"en": "What is the cemetery of Madinah called?", "bn": "মদিনার কবরস্থানের নাম কী?"}', '{"options": [{"en": "Al-Baqi‘", "bn": "জান্নাতুল বাকি"}, {"en": "Al-Ma‘la", "bn": "আল-মালা"}, {"en": "Uhud", "bn": "উহুদ"}, {"en": "Al-Hujurat", "bn": "আল-হুজুরাত"}], "correct": 0}', '{"en": "Many companions are buried in al-Baqi‘.", "bn": "অনেক সাহাবি জান্নাতুল বাকিতে সমাহিত।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('39d1fcd0-4126-5240-9a45-0980e15c1f94', 'c3d46567-369f-5e81-aba2-9481af2582bf', 'choice', '{"en": "Which mountain near Madinah gave its name to a battle?", "bn": "মদিনার কাছের কোন পাহাড়ের নামে একটি যুদ্ধের নাম?"}', '{"options": [{"en": "Uhud", "bn": "উহুদ"}, {"en": "Hira", "bn": "হেরা"}, {"en": "Thawr", "bn": "সাওর"}, {"en": "Safa", "bn": "সাফা"}], "correct": 0}', '{"en": "\"Uhud is a mountain that loves us and we love it.\"", "bn": "\"উহুদ এমন পাহাড়, যা আমাদের ভালোবাসে এবং আমরাও তাকে ভালোবাসি।\""}', 'Sahih al-Bukhari 4084', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f03e966c-a8f2-58af-a6c4-063dbc0ea587', 'c3d46567-369f-5e81-aba2-9481af2582bf', 'choice', '{"en": "What is the cloth covering the Ka‘bah called?", "bn": "কাবার আবরণকে কী বলে?"}', '{"options": [{"en": "Kiswah", "bn": "কিসওয়া"}, {"en": "Ihram", "bn": "ইহরাম"}, {"en": "Mihrab", "bn": "মিহরাব"}, {"en": "Minbar", "bn": "মিম্বর"}], "correct": 0}', '{"en": "The kiswah, renewed every year.", "bn": "কিসওয়া, যা প্রতি বছর নতুন করা হয়।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ea50d091-fd88-5d25-8f8e-a649f618b3be', 'c3d46567-369f-5e81-aba2-9481af2582bf', 'choice', '{"en": "A prayer in Masjid al-Haram is worth how many prayers elsewhere?", "bn": "মসজিদুল হারামে এক নামাজ অন্যত্র কত নামাজের সমান?"}', '{"options": [{"en": "10", "bn": "১০"}, {"en": "1,000", "bn": "১,০০০"}, {"en": "100,000", "bn": "১,০০,০০০"}, {"en": "500", "bn": "৫০০"}], "correct": 2}', '{"en": "\"…a prayer in al-Masjid al-Haram is better than 100,000 prayers elsewhere.\"", "bn": "\"…মসজিদুল হারামে এক নামাজ অন্যত্র এক লাখ নামাজের চেয়ে উত্তম।\""}', 'Sunan Ibn Majah 1406', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('1da37a09-48c7-5e48-b493-cfbf63110d3e', '8002ceae-45f1-50d4-86c8-bfe3fb6da70e', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ba68c9c4-36b8-54bf-af53-6bf714048147', '1da37a09-48c7-5e48-b493-cfbf63110d3e', 'choice', '{"en": "Masjid an-Nabawi (the Prophet’s Mosque) is in…?", "bn": "মসজিদে নববী কোথায়?"}', '{"options": [{"en": "Madinah", "bn": "মদিনা"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Ta’if", "bn": "তায়েফ"}, {"en": "Jeddah", "bn": "জেদ্দা"}], "correct": 0}', '{"en": "He ﷺ built it after the Hijrah.", "bn": "হিজরতের পর তিনি ﷺ এটি নির্মাণ করেন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f593ba75-16b1-543f-bedc-cba97b8013a9', '1da37a09-48c7-5e48-b493-cfbf63110d3e', 'choice', '{"en": "Which was the first mosque the Prophet ﷺ built?", "bn": "নবী ﷺ নির্মিত প্রথম মসজিদ কোনটি?"}', '{"options": [{"en": "Quba", "bn": "কুবা"}, {"en": "Al-Aqsa", "bn": "আল-আকসা"}, {"en": "Al-Haram", "bn": "আল-হারাম"}, {"en": "Al-Qiblatayn", "bn": "আল-কিবলাতাইন"}], "correct": 0}', '{"en": "Built at Quba on the way to Madinah, \"founded on taqwa\".", "bn": "মদিনার পথে কুবায় নির্মিত, \"তাকওয়ার ভিত্তিতে প্রতিষ্ঠিত\"।"}', 'Quran 9:108', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d77c9d20-31f5-5dd1-a1f0-c1020d856175', '1da37a09-48c7-5e48-b493-cfbf63110d3e', 'choice', '{"en": "Where do pilgrims stand on 9 Dhul Hijjah?", "bn": "৯ জিলহজ হাজিরা কোথায় অবস্থান করেন?"}', '{"options": [{"en": "Arafat", "bn": "আরাফাত"}, {"en": "Mina", "bn": "মিনা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Quba", "bn": "কুবা"}], "correct": 0}', '{"en": "The plain of Arafat.", "bn": "আরাফাতের ময়দান।"}', 'Quran 2:198', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fc33651f-7638-5087-8b52-71d44759ce09', '1da37a09-48c7-5e48-b493-cfbf63110d3e', 'choice', '{"en": "Which mountain near Madinah gave its name to a battle?", "bn": "মদিনার কাছের কোন পাহাড়ের নামে একটি যুদ্ধের নাম?"}', '{"options": [{"en": "Uhud", "bn": "উহুদ"}, {"en": "Hira", "bn": "হেরা"}, {"en": "Thawr", "bn": "সাওর"}, {"en": "Safa", "bn": "সাফা"}], "correct": 0}', '{"en": "\"Uhud is a mountain that loves us and we love it.\"", "bn": "\"উহুদ এমন পাহাড়, যা আমাদের ভালোবাসে এবং আমরাও তাকে ভালোবাসি।\""}', 'Sahih al-Bukhari 4084', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d68f253c-571d-5fc3-9ef0-0cfa5539a4da', '1da37a09-48c7-5e48-b493-cfbf63110d3e', 'choice', '{"en": "A prayer in Masjid al-Haram is worth how many prayers elsewhere?", "bn": "মসজিদুল হারামে এক নামাজ অন্যত্র কত নামাজের সমান?"}', '{"options": [{"en": "10", "bn": "১০"}, {"en": "1,000", "bn": "১,০০০"}, {"en": "100,000", "bn": "১,০০,০০০"}, {"en": "500", "bn": "৫০০"}], "correct": 2}', '{"en": "\"…a prayer in al-Masjid al-Haram is better than 100,000 prayers elsewhere.\"", "bn": "\"…মসজিদুল হারামে এক নামাজ অন্যত্র এক লাখ নামাজের চেয়ে উত্তম।\""}', 'Sunan Ibn Majah 1406', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9cbe29be-ff50-5d66-851c-e52cc16ea7d1', '1da37a09-48c7-5e48-b493-cfbf63110d3e', 'choice', '{"en": "Masjid al-Haram is in…?", "bn": "মসজিদুল হারাম কোথায়?"}', '{"options": [{"en": "Makkah", "bn": "মক্কা"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Jerusalem", "bn": "জেরুজালেম"}, {"en": "Damascus", "bn": "দামেস্ক"}], "correct": 0}', '{"en": "It surrounds the Ka‘bah.", "bn": "এটি কাবাকে ঘিরে আছে।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('b281d45e-a551-517a-95c4-ae9d65dcf400', '{"en": "Hadith & the great scholars", "bn": "হাদিস ও মহান আলেমগণ"}', '{}', '#9c88ff', 'library', 'in_review', 1, '202f7c3c-3e18-5b55-b213-a24b20c92fcd') ON CONFLICT (id) DO NOTHING;
