INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('57669f0f-dbdd-5c81-9c8b-c185c1ac4377', 'ad60db3b-4157-5ca1-978d-d5f7b91b48a0', 'choice', '{"en": "The six major hadith books are called…?", "bn": "হাদিসের ছয়টি প্রধান গ্রন্থকে কী বলে?"}', '{"options": [{"en": "Kutub as-Sittah", "bn": "সিহাহ সিত্তাহ (কুতুবুস সিত্তাহ)"}, {"en": "Al-Mu‘allaqat", "bn": "আল-মুআল্লাকাত"}, {"en": "Al-Masahif", "bn": "আল-মাসাহিফ"}, {"en": "Al-Mutun", "bn": "আল-মুতুন"}], "correct": 0}', '{"en": "Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasa’i and Ibn Majah.", "bn": "বুখারি, মুসলিম, আবু দাউদ, তিরমিজি, নাসায়ি ও ইবনে মাজাহ।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('5101e4c0-d5e7-5cb6-8064-5364f8ae5c2e', 'ad60db3b-4157-5ca1-978d-d5f7b91b48a0', 'choice', '{"en": "Which book do scholars call the most authentic after the Quran?", "bn": "আলেমদের মতে কুরআনের পর সবচেয়ে বিশুদ্ধ গ্রন্থ কোনটি?"}', '{"options": [{"en": "Sahih al-Bukhari", "bn": "সহিহ বুখারি"}, {"en": "Al-Muwatta", "bn": "মুয়াত্তা"}, {"en": "Sunan Ibn Majah", "bn": "সুনানে ইবনে মাজাহ"}, {"en": "Riyad as-Salihin", "bn": "রিয়াদুস সালিহিন"}], "correct": 0}', '{"en": "Sahih al-Bukhari, then Sahih Muslim.", "bn": "সহিহ বুখারি, তারপর সহিহ মুসলিম।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8c98c887-3e24-5d65-a9d9-c9cbea81386a', 'ad60db3b-4157-5ca1-978d-d5f7b91b48a0', 'choice', '{"en": "Most Muslims in Bangladesh follow which school (madhhab)?", "bn": "বাংলাদেশের অধিকাংশ মুসলমান কোন মাজহাব অনুসরণ করেন?"}', '{"options": [{"en": "Hanafi", "bn": "হানাফি"}, {"en": "Maliki", "bn": "মালিকি"}, {"en": "Shafi‘i", "bn": "শাফেয়ি"}, {"en": "Hanbali", "bn": "হাম্বলি"}], "correct": 0}', '{"en": "The school of Imam Abu Hanifah.", "bn": "ইমাম আবু হানিফার মাজহাব।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('90596209-a6f1-5748-8723-d6f435fe7c2e', 'ad60db3b-4157-5ca1-978d-d5f7b91b48a0', 'choice', '{"en": "Who compiled al-Muwatta’?", "bn": "মুয়াত্তা কে সংকলন করেন?"}', '{"options": [{"en": "Imam Malik", "bn": "ইমাম মালিক"}, {"en": "Imam Abu Hanifah", "bn": "ইমাম আবু হানিফা"}, {"en": "Imam Muslim", "bn": "ইমাম মুসলিম"}, {"en": "Imam an-Nawawi", "bn": "ইমাম নববি"}], "correct": 0}', '{"en": "Imam Malik of Madinah.", "bn": "মদিনার ইমাম মালিক।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e544244b-7a07-5eeb-919c-39f56b515f15', 'ad60db3b-4157-5ca1-978d-d5f7b91b48a0', 'choice', '{"en": "Who compiled al-Musnad, one of the largest hadith collections?", "bn": "বৃহত্তম হাদিস সংকলনগুলোর একটি আল-মুসনাদ কে সংকলন করেন?"}', '{"options": [{"en": "Imam Ahmad ibn Hanbal", "bn": "ইমাম আহমাদ ইবনে হাম্বল"}, {"en": "Imam ash-Shafi‘i", "bn": "ইমাম শাফেয়ি"}, {"en": "Ibn Kathir", "bn": "ইবনে কাসির"}, {"en": "Imam Malik", "bn": "ইমাম মালিক"}], "correct": 0}', '{"en": "Musnad Ahmad, arranged by companion.", "bn": "মুসনাদে আহমাদ, সাহাবি অনুযায়ী বিন্যস্ত।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('a808a3ba-95fa-5bbe-8ce4-dd856494d3fe', 'b281d45e-a551-517a-95c4-ae9d65dcf400', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9a8f83c6-c995-53c7-a343-1354c212be82', 'a808a3ba-95fa-5bbe-8ce4-dd856494d3fe', 'choice', '{"en": "Imam ash-Shafi‘i’s famous book on the principles of fiqh is…?", "bn": "ফিকহের মূলনীতি বিষয়ে ইমাম শাফেয়ির প্রসিদ্ধ গ্রন্থ কোনটি?"}', '{"options": [{"en": "Ar-Risalah", "bn": "আর-রিসালাহ"}, {"en": "Ihya’", "bn": "ইহইয়া"}, {"en": "Al-Muqaddimah", "bn": "আল-মুকাদ্দিমা"}, {"en": "Al-Hidayah", "bn": "আল-হিদায়া"}], "correct": 0}', '{"en": "Ar-Risalah is among the first works on usul al-fiqh.", "bn": "আর-রিসালাহ উসুলুল ফিকহের প্রথম দিকের গ্রন্থগুলোর একটি।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('db4442fd-5dc8-55ee-b1c8-6cf0238747a8', 'a808a3ba-95fa-5bbe-8ce4-dd856494d3fe', 'choice', '{"en": "The chain of narrators of a hadith is called…?", "bn": "হাদিসের বর্ণনাকারীদের ধারাকে কী বলে?"}', '{"options": [{"en": "Isnad", "bn": "ইসনাদ (সনদ)"}, {"en": "Matn", "bn": "মতন"}, {"en": "Tafsir", "bn": "তাফসির"}, {"en": "Ijma‘", "bn": "ইজমা"}], "correct": 0}', '{"en": "Isnad: who narrated it from whom.", "bn": "ইসনাদ: কে কার কাছ থেকে বর্ণনা করেছেন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('59b214a4-eeee-54ce-a2fc-ef2b748c46e4', 'a808a3ba-95fa-5bbe-8ce4-dd856494d3fe', 'choice', '{"en": "The text of a hadith itself is called…?", "bn": "হাদিসের মূল বক্তব্যকে কী বলে?"}', '{"options": [{"en": "Matn", "bn": "মতন"}, {"en": "Isnad", "bn": "ইসনাদ"}, {"en": "Sharh", "bn": "শরাহ"}, {"en": "Fatwa", "bn": "ফতোয়া"}], "correct": 0}', '{"en": "The matn is what the Prophet ﷺ said or did.", "bn": "মতন হলো নবী ﷺ যা বলেছেন বা করেছেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('aefbccff-df5d-593d-aa20-af07756b1333', 'a808a3ba-95fa-5bbe-8ce4-dd856494d3fe', 'choice', '{"en": "A hadith in which the Prophet ﷺ relates Allah’s words is called…?", "bn": "যে হাদিসে নবী ﷺ আল্লাহর বাণী বর্ণনা করেন তাকে কী বলে?"}', '{"options": [{"en": "Hadith qudsi", "bn": "হাদিসে কুদসি"}, {"en": "Hadith mawdu‘", "bn": "হাদিসে মাওজু"}, {"en": "Athar", "bn": "আসার"}, {"en": "Sirah", "bn": "সিরাহ"}], "correct": 0}', '{"en": "For example: \"Fasting is for Me and I will reward it.\"", "bn": "যেমন: \"রোজা আমার জন্য এবং আমিই এর প্রতিদান দেব।\""}', 'Sahih al-Bukhari 1904', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a3cc6b97-bf91-5928-9ab0-d38092a366b0', 'a808a3ba-95fa-5bbe-8ce4-dd856494d3fe', 'choice', '{"en": "Who compiled Riyad as-Salihin?", "bn": "রিয়াদুস সালিহিন কে সংকলন করেন?"}', '{"options": [{"en": "Imam an-Nawawi", "bn": "ইমাম নববি"}, {"en": "Imam al-Bukhari", "bn": "ইমাম বুখারি"}, {"en": "Ibn Taymiyyah", "bn": "ইবনে তাইমিয়া"}, {"en": "Al-Ghazali", "bn": "আল-গাজালি"}], "correct": 0}', '{"en": "Imam Yahya ibn Sharaf an-Nawawi.", "bn": "ইমাম ইয়াহইয়া ইবনে শারাফ আন-নববি।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'b281d45e-a551-517a-95c4-ae9d65dcf400', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('79adac1b-3c2f-574c-a873-31dbd9da4ebe', 'ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'choice', '{"en": "Which book do scholars call the most authentic after the Quran?", "bn": "আলেমদের মতে কুরআনের পর সবচেয়ে বিশুদ্ধ গ্রন্থ কোনটি?"}', '{"options": [{"en": "Sahih al-Bukhari", "bn": "সহিহ বুখারি"}, {"en": "Al-Muwatta", "bn": "মুয়াত্তা"}, {"en": "Sunan Ibn Majah", "bn": "সুনানে ইবনে মাজাহ"}, {"en": "Riyad as-Salihin", "bn": "রিয়াদুস সালিহিন"}], "correct": 0}', '{"en": "Sahih al-Bukhari, then Sahih Muslim.", "bn": "সহিহ বুখারি, তারপর সহিহ মুসলিম।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bec32210-5ed4-55a9-ba47-ba0e8455609c', 'ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'choice', '{"en": "Who compiled al-Muwatta’?", "bn": "মুয়াত্তা কে সংকলন করেন?"}', '{"options": [{"en": "Imam Malik", "bn": "ইমাম মালিক"}, {"en": "Imam Abu Hanifah", "bn": "ইমাম আবু হানিফা"}, {"en": "Imam Muslim", "bn": "ইমাম মুসলিম"}, {"en": "Imam an-Nawawi", "bn": "ইমাম নববি"}], "correct": 0}', '{"en": "Imam Malik of Madinah.", "bn": "মদিনার ইমাম মালিক।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d79d7b17-9e69-51f4-aef1-9b2d787209b5', 'ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'choice', '{"en": "Imam ash-Shafi‘i’s famous book on the principles of fiqh is…?", "bn": "ফিকহের মূলনীতি বিষয়ে ইমাম শাফেয়ির প্রসিদ্ধ গ্রন্থ কোনটি?"}', '{"options": [{"en": "Ar-Risalah", "bn": "আর-রিসালাহ"}, {"en": "Ihya’", "bn": "ইহইয়া"}, {"en": "Al-Muqaddimah", "bn": "আল-মুকাদ্দিমা"}, {"en": "Al-Hidayah", "bn": "আল-হিদায়া"}], "correct": 0}', '{"en": "Ar-Risalah is among the first works on usul al-fiqh.", "bn": "আর-রিসালাহ উসুলুল ফিকহের প্রথম দিকের গ্রন্থগুলোর একটি।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('2e247bbc-0788-5c6e-8dc2-38c42a398d2a', 'ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'choice', '{"en": "The text of a hadith itself is called…?", "bn": "হাদিসের মূল বক্তব্যকে কী বলে?"}', '{"options": [{"en": "Matn", "bn": "মতন"}, {"en": "Isnad", "bn": "ইসনাদ"}, {"en": "Sharh", "bn": "শরাহ"}, {"en": "Fatwa", "bn": "ফতোয়া"}], "correct": 0}', '{"en": "The matn is what the Prophet ﷺ said or did.", "bn": "মতন হলো নবী ﷺ যা বলেছেন বা করেছেন।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a2033e57-0604-55d8-9efb-352c839dfb25', 'ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'choice', '{"en": "Who compiled Riyad as-Salihin?", "bn": "রিয়াদুস সালিহিন কে সংকলন করেন?"}', '{"options": [{"en": "Imam an-Nawawi", "bn": "ইমাম নববি"}, {"en": "Imam al-Bukhari", "bn": "ইমাম বুখারি"}, {"en": "Ibn Taymiyyah", "bn": "ইবনে তাইমিয়া"}, {"en": "Al-Ghazali", "bn": "আল-গাজালি"}], "correct": 0}', '{"en": "Imam Yahya ibn Sharaf an-Nawawi.", "bn": "ইমাম ইয়াহইয়া ইবনে শারাফ আন-নববি।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('51b32e40-a365-5137-ab59-4fd89bf2576a', 'ae8d6437-7b8e-525a-ac51-91378ea00bbf', 'choice', '{"en": "The six major hadith books are called…?", "bn": "হাদিসের ছয়টি প্রধান গ্রন্থকে কী বলে?"}', '{"options": [{"en": "Kutub as-Sittah", "bn": "সিহাহ সিত্তাহ (কুতুবুস সিত্তাহ)"}, {"en": "Al-Mu‘allaqat", "bn": "আল-মুআল্লাকাত"}, {"en": "Al-Masahif", "bn": "আল-মাসাহিফ"}, {"en": "Al-Mutun", "bn": "আল-মুতুন"}], "correct": 0}', '{"en": "Bukhari, Muslim, Abu Dawud, Tirmidhi, Nasa’i and Ibn Majah.", "bn": "বুখারি, মুসলিম, আবু দাউদ, তিরমিজি, নাসায়ি ও ইবনে মাজাহ।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
