INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('68427d66-6f3d-5bed-b794-8e6a99ea8e2c', '4ac277a6-b947-516b-bb71-a61c9b1ed53c', 'choice', '{"en": "Al-Khwarizmi is best known for…?", "bn": "আল-খোয়ারিজমি কীসের জন্য সবচেয়ে প্রসিদ্ধ?"}', '{"options": [{"en": "Algebra", "bn": "বীজগণিত"}, {"en": "Poetry", "bn": "কবিতা"}, {"en": "Architecture", "bn": "স্থাপত্য"}, {"en": "Music", "bn": "সংগীত"}], "correct": 0}', '{"en": "\"Algebra\" comes from his book, and \"algorithm\" from his name.", "bn": "\"অ্যালজেব্রা\" তাঁর বই থেকে, আর \"অ্যালগরিদম\" তাঁর নাম থেকে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1c5cab0f-23c7-59c9-ace8-02f41941eae4', '4ac277a6-b947-516b-bb71-a61c9b1ed53c', 'choice', '{"en": "Ibn Sina wrote the famous…?", "bn": "ইবনে সিনা কোন প্রসিদ্ধ গ্রন্থ লেখেন?"}', '{"options": [{"en": "Canon of Medicine", "bn": "আল-কানুন ফিত তিব"}, {"en": "Muqaddimah", "bn": "মুকাদ্দিমা"}, {"en": "Rihla", "bn": "রিহলা"}, {"en": "Book of Optics", "bn": "কিতাবুল মানাজির"}], "correct": 0}', '{"en": "Al-Qanun fi al-Tibb was taught in medical schools for centuries.", "bn": "আল-কানুন ফিত তিব শত শত বছর চিকিৎসা শিক্ষায় পড়ানো হয়েছে।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f930f9f6-7e6a-5393-ada0-61b019e3bfec', '4ac277a6-b947-516b-bb71-a61c9b1ed53c', 'choice', '{"en": "Ibn al-Haytham is famous for his work on…?", "bn": "ইবনুল হাইসাম কোন বিষয়ে কাজের জন্য প্রসিদ্ধ?"}', '{"options": [{"en": "Optics (light and vision)", "bn": "আলোকবিজ্ঞান (আলো ও দৃষ্টি)"}, {"en": "Farming", "bn": "কৃষি"}, {"en": "Geography", "bn": "ভূগোল"}, {"en": "Law", "bn": "আইন"}], "correct": 0}', '{"en": "His Book of Optics explained how we see, using experiments.", "bn": "তাঁর কিতাবুল মানাজির পরীক্ষার মাধ্যমে দেখার প্রক্রিয়া ব্যাখ্যা করে।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e51ed289-94e8-5b9d-8849-5bc38ab93d00', '4ac277a6-b947-516b-bb71-a61c9b1ed53c', 'choice', '{"en": "Al-Biruni estimated the size of…?", "bn": "আল-বিরুনি কীসের আকার নির্ণয় করেছিলেন?"}', '{"options": [{"en": "The Earth", "bn": "পৃথিবী"}, {"en": "The Moon’s craters", "bn": "চাঁদের গর্ত"}, {"en": "Atoms", "bn": "পরমাণু"}, {"en": "Mount Everest", "bn": "এভারেস্ট"}], "correct": 0}', '{"en": "He measured the Earth’s radius remarkably closely.", "bn": "তিনি পৃথিবীর ব্যাসার্ধ উল্লেখযোগ্য নিখুঁতভাবে মাপেন।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b9b359be-1ba2-5473-bb1a-28fa9b7dee0d', '4ac277a6-b947-516b-bb71-a61c9b1ed53c', 'choice', '{"en": "Al-Zahrawi is often called the father of…?", "bn": "আল-জাহরাবিকে প্রায়ই কীসের জনক বলা হয়?"}', '{"options": [{"en": "Surgery", "bn": "শল্যচিকিৎসা"}, {"en": "Chemistry", "bn": "রসায়ন"}, {"en": "Astronomy", "bn": "জ্যোতির্বিদ্যা"}, {"en": "Geometry", "bn": "জ্যামিতি"}], "correct": 0}', '{"en": "His encyclopedia described many surgical tools.", "bn": "তাঁর বিশ্বকোষে বহু অস্ত্রোপচার যন্ত্রের বর্ণনা আছে।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('47d37760-5952-51c0-b1e3-d4af26d0b26e', '6e16f172-38a5-5f9e-adb2-8c26fa9c3fce', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('00bd527e-4546-5587-a058-fd3370a52924', '47d37760-5952-51c0-b1e3-d4af26d0b26e', 'choice', '{"en": "Ibn Battuta is famous as a great…?", "bn": "ইবনে বতুতা মহান কী হিসেবে প্রসিদ্ধ?"}', '{"options": [{"en": "Traveller", "bn": "পর্যটক"}, {"en": "Poet", "bn": "কবি"}, {"en": "Doctor", "bn": "চিকিৎসক"}, {"en": "King", "bn": "রাজা"}], "correct": 0}', '{"en": "He travelled for about thirty years, including to Bengal.", "bn": "তিনি প্রায় ত্রিশ বছর ভ্রমণ করেন, বাংলাতেও এসেছিলেন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('322ff313-787c-5197-9a96-de375230c46d', '47d37760-5952-51c0-b1e3-d4af26d0b26e', 'choice', '{"en": "Ibn Khaldun wrote the…?", "bn": "ইবনে খালদুন কোন গ্রন্থ লেখেন?"}', '{"options": [{"en": "Muqaddimah", "bn": "মুকাদ্দিমা"}, {"en": "Canon", "bn": "কানুন"}, {"en": "Shahnameh", "bn": "শাহনামা"}, {"en": "Ihya’", "bn": "ইহইয়া"}], "correct": 0}', '{"en": "A founding work of history and social science.", "bn": "ইতিহাস ও সমাজবিজ্ঞানের ভিত্তিমূলক গ্রন্থ।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e591d9ea-dc76-5c4f-b6c4-0cb510bda174', '47d37760-5952-51c0-b1e3-d4af26d0b26e', 'choice', '{"en": "Al-Jazari is remembered for…?", "bn": "আল-জাজারি কীসের জন্য স্মরণীয়?"}', '{"options": [{"en": "Ingenious machines", "bn": "বিস্ময়কর যন্ত্র"}, {"en": "Hadith collection", "bn": "হাদিস সংকলন"}, {"en": "Calligraphy", "bn": "ক্যালিগ্রাফি"}, {"en": "Maps", "bn": "মানচিত্র"}], "correct": 0}', '{"en": "His Book of Ingenious Mechanical Devices described clocks and automata.", "bn": "তাঁর যন্ত্রবিষয়ক গ্রন্থে ঘড়ি ও স্বয়ংক্রিয় যন্ত্রের বর্ণনা আছে।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fe696302-54c2-593d-8e86-3a1e9beb7e52', '47d37760-5952-51c0-b1e3-d4af26d0b26e', 'choice', '{"en": "Fatima al-Fihri founded…?", "bn": "ফাতিমা আল-ফিহরি কী প্রতিষ্ঠা করেন?"}', '{"options": [{"en": "Al-Qarawiyyin in Fez", "bn": "ফেজের আল-কারাউইন"}, {"en": "Al-Azhar in Cairo", "bn": "কায়রোর আল-আজহার"}, {"en": "A hospital in Baghdad", "bn": "বাগদাদের হাসপাতাল"}, {"en": "A library in Cordoba", "bn": "কর্ডোভার গ্রন্থাগার"}], "correct": 0}', '{"en": "Founded in 859, often called the oldest existing university.", "bn": "৮৫৯ সালে প্রতিষ্ঠিত, প্রায়ই প্রাচীনতম চালু বিশ্ববিদ্যালয় বলা হয়।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('108120e1-a33c-548a-8e84-cf81b46646dd', '47d37760-5952-51c0-b1e3-d4af26d0b26e', 'choice', '{"en": "Europe learned the \"Arabic numerals\" (0–9), which came originally from…?", "bn": "ইউরোপ যে \"আরবি সংখ্যা\" (০–৯) শিখেছিল, তা মূলত কোথা থেকে এসেছিল?"}', '{"options": [{"en": "India, through Muslim scholars", "bn": "ভারত থেকে, মুসলিম পণ্ডিতদের মাধ্যমে"}, {"en": "Rome", "bn": "রোম"}, {"en": "China only", "bn": "শুধু চীন"}, {"en": "Greece", "bn": "গ্রিস"}], "correct": 0}', '{"en": "Muslim mathematicians like al-Khwarizmi spread them.", "bn": "আল-খোয়ারিজমির মতো মুসলিম গণিতবিদরা এগুলো ছড়িয়ে দেন।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('1e8bf30c-b568-5f54-839e-91b8f35fdd16', '6e16f172-38a5-5f9e-adb2-8c26fa9c3fce', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7ad9ca03-99e6-569f-9647-8b91a63a1b93', '1e8bf30c-b568-5f54-839e-91b8f35fdd16', 'choice', '{"en": "Ibn Sina wrote the famous…?", "bn": "ইবনে সিনা কোন প্রসিদ্ধ গ্রন্থ লেখেন?"}', '{"options": [{"en": "Canon of Medicine", "bn": "আল-কানুন ফিত তিব"}, {"en": "Muqaddimah", "bn": "মুকাদ্দিমা"}, {"en": "Rihla", "bn": "রিহলা"}, {"en": "Book of Optics", "bn": "কিতাবুল মানাজির"}], "correct": 0}', '{"en": "Al-Qanun fi al-Tibb was taught in medical schools for centuries.", "bn": "আল-কানুন ফিত তিব শত শত বছর চিকিৎসা শিক্ষায় পড়ানো হয়েছে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('697b383e-767b-5f52-b14d-6aedbde721ca', '1e8bf30c-b568-5f54-839e-91b8f35fdd16', 'choice', '{"en": "Al-Biruni estimated the size of…?", "bn": "আল-বিরুনি কীসের আকার নির্ণয় করেছিলেন?"}', '{"options": [{"en": "The Earth", "bn": "পৃথিবী"}, {"en": "The Moon’s craters", "bn": "চাঁদের গর্ত"}, {"en": "Atoms", "bn": "পরমাণু"}, {"en": "Mount Everest", "bn": "এভারেস্ট"}], "correct": 0}', '{"en": "He measured the Earth’s radius remarkably closely.", "bn": "তিনি পৃথিবীর ব্যাসার্ধ উল্লেখযোগ্য নিখুঁতভাবে মাপেন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('16829843-1888-5cbe-99b1-2f932b844361', '1e8bf30c-b568-5f54-839e-91b8f35fdd16', 'choice', '{"en": "Ibn Battuta is famous as a great…?", "bn": "ইবনে বতুতা মহান কী হিসেবে প্রসিদ্ধ?"}', '{"options": [{"en": "Traveller", "bn": "পর্যটক"}, {"en": "Poet", "bn": "কবি"}, {"en": "Doctor", "bn": "চিকিৎসক"}, {"en": "King", "bn": "রাজা"}], "correct": 0}', '{"en": "He travelled for about thirty years, including to Bengal.", "bn": "তিনি প্রায় ত্রিশ বছর ভ্রমণ করেন, বাংলাতেও এসেছিলেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('461660f5-71fe-5209-b2a4-ad118fdd772a', '1e8bf30c-b568-5f54-839e-91b8f35fdd16', 'choice', '{"en": "Al-Jazari is remembered for…?", "bn": "আল-জাজারি কীসের জন্য স্মরণীয়?"}', '{"options": [{"en": "Ingenious machines", "bn": "বিস্ময়কর যন্ত্র"}, {"en": "Hadith collection", "bn": "হাদিস সংকলন"}, {"en": "Calligraphy", "bn": "ক্যালিগ্রাফি"}, {"en": "Maps", "bn": "মানচিত্র"}], "correct": 0}', '{"en": "His Book of Ingenious Mechanical Devices described clocks and automata.", "bn": "তাঁর যন্ত্রবিষয়ক গ্রন্থে ঘড়ি ও স্বয়ংক্রিয় যন্ত্রের বর্ণনা আছে।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fff4c1c1-601c-57d6-9a07-9a7d20b0bda1', '1e8bf30c-b568-5f54-839e-91b8f35fdd16', 'choice', '{"en": "Europe learned the \"Arabic numerals\" (0–9), which came originally from…?", "bn": "ইউরোপ যে \"আরবি সংখ্যা\" (০–৯) শিখেছিল, তা মূলত কোথা থেকে এসেছিল?"}', '{"options": [{"en": "India, through Muslim scholars", "bn": "ভারত থেকে, মুসলিম পণ্ডিতদের মাধ্যমে"}, {"en": "Rome", "bn": "রোম"}, {"en": "China only", "bn": "শুধু চীন"}, {"en": "Greece", "bn": "গ্রিস"}], "correct": 0}', '{"en": "Muslim mathematicians like al-Khwarizmi spread them.", "bn": "আল-খোয়ারিজমির মতো মুসলিম গণিতবিদরা এগুলো ছড়িয়ে দেন।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7e67b714-4bb4-5033-829b-f4390cc1e300', '1e8bf30c-b568-5f54-839e-91b8f35fdd16', 'choice', '{"en": "Al-Khwarizmi is best known for…?", "bn": "আল-খোয়ারিজমি কীসের জন্য সবচেয়ে প্রসিদ্ধ?"}', '{"options": [{"en": "Algebra", "bn": "বীজগণিত"}, {"en": "Poetry", "bn": "কবিতা"}, {"en": "Architecture", "bn": "স্থাপত্য"}, {"en": "Music", "bn": "সংগীত"}], "correct": 0}', '{"en": "\"Algebra\" comes from his book, and \"algorithm\" from his name.", "bn": "\"অ্যালজেব্রা\" তাঁর বই থেকে, আর \"অ্যালগরিদম\" তাঁর নাম থেকে।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
