INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('82c033d0-c7d2-51d6-be36-425809889bbf', '917718af-0e67-5a71-860d-bd9ad49492ae', 'choice', '{"en": "What was the capital of the Umayyad caliphate?", "bn": "উমাইয়া খিলাফতের রাজধানী কোথায় ছিল?"}', '{"options": [{"en": "Damascus", "bn": "দামেস্ক"}, {"en": "Baghdad", "bn": "বাগদাদ"}, {"en": "Cairo", "bn": "কায়রো"}, {"en": "Istanbul", "bn": "ইস্তাম্বুল"}], "correct": 0}', '{"en": "The Umayyads ruled from Damascus.", "bn": "উমাইয়ারা দামেস্ক থেকে শাসন করত।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b5520b36-e547-57ef-bb27-6e74f5431161', '917718af-0e67-5a71-860d-bd9ad49492ae', 'choice', '{"en": "What was the capital of the Abbasid caliphate?", "bn": "আব্বাসি খিলাফতের রাজধানী কোথায় ছিল?"}', '{"options": [{"en": "Baghdad", "bn": "বাগদাদ"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Cordoba", "bn": "কর্ডোভা"}, {"en": "Damascus", "bn": "দামেস্ক"}], "correct": 0}', '{"en": "The Abbasids founded Baghdad as their capital.", "bn": "আব্বাসিরা বাগদাদকে রাজধানী হিসেবে গড়ে তোলে।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0dac5a22-b4a5-529e-9323-bea9bf1b52b6', '917718af-0e67-5a71-860d-bd9ad49492ae', 'choice', '{"en": "Who freed Jerusalem in 1187?", "bn": "১১৮৭ সালে জেরুজালেম কে মুক্ত করেন?"}', '{"options": [{"en": "Salahuddin al-Ayyubi", "bn": "সালাহউদ্দিন আইয়ুবি"}, {"en": "Harun ar-Rashid", "bn": "হারুনুর রশিদ"}, {"en": "Tariq ibn Ziyad", "bn": "তারিক ইবনে যিয়াদ"}, {"en": "Muhammad al-Fatih", "bn": "মুহাম্মাদ আল-ফাতিহ"}], "correct": 0}', '{"en": "Salahuddin retook Jerusalem after the Battle of Hattin.", "bn": "হিত্তিনের যুদ্ধের পর সালাহউদ্দিন জেরুজালেম পুনরুদ্ধার করেন।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8bd154ad-03be-5cc8-89c8-72e6bb137120', '917718af-0e67-5a71-860d-bd9ad49492ae', 'choice', '{"en": "Who conquered Constantinople in 1453?", "bn": "১৪৫৩ সালে কনস্টান্টিনোপল কে জয় করেন?"}', '{"options": [{"en": "Sultan Muhammad al-Fatih", "bn": "সুলতান মুহাম্মাদ আল-ফাতিহ"}, {"en": "Salahuddin", "bn": "সালাহউদ্দিন"}, {"en": "Suleiman", "bn": "সুলাইমান"}, {"en": "Babur", "bn": "বাবর"}], "correct": 0}', '{"en": "The Ottoman sultan Mehmed II, \"the Conqueror\".", "bn": "উসমানি সুলতান দ্বিতীয় মুহাম্মাদ, \"বিজেতা\"।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1671547d-75d6-525a-a9e4-20c05b50ff07', '917718af-0e67-5a71-860d-bd9ad49492ae', 'choice', '{"en": "What was Muslim-ruled Spain called?", "bn": "মুসলিম-শাসিত স্পেনকে কী বলা হতো?"}', '{"options": [{"en": "Al-Andalus", "bn": "আন্দালুস"}, {"en": "Al-Maghrib", "bn": "মাগরিব"}, {"en": "Al-Hijaz", "bn": "হিজাজ"}, {"en": "Al-Sham", "bn": "শাম"}], "correct": 0}', '{"en": "Al-Andalus, from 711 until Granada fell in 1492.", "bn": "আন্দালুস, ৭১১ থেকে ১৪৯২ সালে গ্রানাডার পতন পর্যন্ত।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('fe05a80d-9b32-5a53-98ae-f2076e93e721', '2af90c92-adb0-5bb6-8344-2e474ca9e375', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cbc4b2a9-c920-5df9-a5e7-f84ffabf3fdb', 'fe05a80d-9b32-5a53-98ae-f2076e93e721', 'choice', '{"en": "Which commander crossed into Spain in 711 (Gibraltar is named after him)?", "bn": "কোন সেনাপতি ৭১১ সালে স্পেনে প্রবেশ করেন (জিব্রাল্টার তাঁর নামে)?"}', '{"options": [{"en": "Tariq ibn Ziyad", "bn": "তারিক ইবনে যিয়াদ"}, {"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ"}, {"en": "‘Amr ibn al-‘As", "bn": "আমর ইবনুল আস"}, {"en": "Musa ibn Nusayr", "bn": "মুসা ইবনে নুসাইর"}], "correct": 0}', '{"en": "Jabal Tariq, \"Mount of Tariq\", became Gibraltar.", "bn": "জাবালুত তারিক, \"তারিকের পাহাড়\", থেকে জিব্রাল্টার।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7aeb9b52-7503-5abd-a42e-e33602dab273', 'fe05a80d-9b32-5a53-98ae-f2076e93e721', 'choice', '{"en": "Which Umayyad caliph is famous for his justice, often called the fifth rightly guided caliph?", "bn": "কোন উমাইয়া খলিফা ন্যায়পরায়ণতার জন্য প্রসিদ্ধ, যাঁকে পঞ্চম খলিফায়ে রাশেদ বলা হয়?"}', '{"options": [{"en": "‘Umar ibn ‘Abd al-‘Aziz", "bn": "উমর ইবনে আবদুল আজিজ"}, {"en": "Yazid", "bn": "ইয়াজিদ"}, {"en": "Marwan", "bn": "মারওয়ান"}, {"en": "Al-Walid", "bn": "আল-ওয়ালিদ"}], "correct": 0}', '{"en": "‘Umar ibn ‘Abd al-‘Aziz ruled about two and a half years with great justice.", "bn": "উমর ইবনে আবদুল আজিজ প্রায় আড়াই বছর মহান ন্যায়ের সাথে শাসন করেন।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1335e4a1-122b-5d75-b05e-42da0e78c043', 'fe05a80d-9b32-5a53-98ae-f2076e93e721', 'choice', '{"en": "The \"House of Wisdom\" (Bayt al-Hikmah) was in…?", "bn": "\"বাইতুল হিকমাহ\" (জ্ঞানের ঘর) কোথায় ছিল?"}', '{"options": [{"en": "Baghdad", "bn": "বাগদাদ"}, {"en": "Cordoba", "bn": "কর্ডোভা"}, {"en": "Makkah", "bn": "মক্কা"}, {"en": "Delhi", "bn": "দিল্লি"}], "correct": 0}', '{"en": "A great Abbasid centre of translation and learning.", "bn": "আব্বাসি আমলের অনুবাদ ও জ্ঞানচর্চার মহাকেন্দ্র।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('28fd5977-e40e-568f-95d9-251739d24714', 'fe05a80d-9b32-5a53-98ae-f2076e93e721', 'choice', '{"en": "The Great Mosque of Cordoba is in which country today?", "bn": "কর্ডোভার বড় মসজিদ আজ কোন দেশে?"}', '{"options": [{"en": "Spain", "bn": "স্পেন"}, {"en": "Morocco", "bn": "মরক্কো"}, {"en": "Turkey", "bn": "তুরস্ক"}, {"en": "Egypt", "bn": "মিশর"}], "correct": 0}', '{"en": "Built under the Umayyads of al-Andalus.", "bn": "আন্দালুসের উমাইয়াদের আমলে নির্মিত।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('3a120724-852f-548f-bb7c-7871c59cd43b', 'fe05a80d-9b32-5a53-98ae-f2076e93e721', 'choice', '{"en": "After 1453, which city became the Ottoman capital?", "bn": "১৪৫৩ সালের পর কোন শহর উসমানি রাজধানী হয়?"}', '{"options": [{"en": "Istanbul", "bn": "ইস্তাম্বুল"}, {"en": "Ankara", "bn": "আঙ্কারা"}, {"en": "Bursa", "bn": "বুরসা"}, {"en": "Cairo", "bn": "কায়রো"}], "correct": 0}', '{"en": "Constantinople, renamed Istanbul.", "bn": "কনস্টান্টিনোপল, যার নাম হয় ইস্তাম্বুল।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('9163fb5b-aaf1-5c6c-9f8a-57da1ebdbe81', '2af90c92-adb0-5bb6-8344-2e474ca9e375', '{"en": "Unit review", "bn": "ইউনিট রিভিউ"}', 'checkpoint', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('93897f8f-3d62-5706-aca2-454ec44aa5af', '9163fb5b-aaf1-5c6c-9f8a-57da1ebdbe81', 'choice', '{"en": "What was the capital of the Abbasid caliphate?", "bn": "আব্বাসি খিলাফতের রাজধানী কোথায় ছিল?"}', '{"options": [{"en": "Baghdad", "bn": "বাগদাদ"}, {"en": "Madinah", "bn": "মদিনা"}, {"en": "Cordoba", "bn": "কর্ডোভা"}, {"en": "Damascus", "bn": "দামেস্ক"}], "correct": 0}', '{"en": "The Abbasids founded Baghdad as their capital.", "bn": "আব্বাসিরা বাগদাদকে রাজধানী হিসেবে গড়ে তোলে।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('7afb9a53-1eaa-50c9-a298-eaa55a888ab1', '9163fb5b-aaf1-5c6c-9f8a-57da1ebdbe81', 'choice', '{"en": "Who conquered Constantinople in 1453?", "bn": "১৪৫৩ সালে কনস্টান্টিনোপল কে জয় করেন?"}', '{"options": [{"en": "Sultan Muhammad al-Fatih", "bn": "সুলতান মুহাম্মাদ আল-ফাতিহ"}, {"en": "Salahuddin", "bn": "সালাহউদ্দিন"}, {"en": "Suleiman", "bn": "সুলাইমান"}, {"en": "Babur", "bn": "বাবর"}], "correct": 0}', '{"en": "The Ottoman sultan Mehmed II, \"the Conqueror\".", "bn": "উসমানি সুলতান দ্বিতীয় মুহাম্মাদ, \"বিজেতা\"।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('abfa9081-3562-5a24-9c7a-f921f639ac0c', '9163fb5b-aaf1-5c6c-9f8a-57da1ebdbe81', 'choice', '{"en": "Which commander crossed into Spain in 711 (Gibraltar is named after him)?", "bn": "কোন সেনাপতি ৭১১ সালে স্পেনে প্রবেশ করেন (জিব্রাল্টার তাঁর নামে)?"}', '{"options": [{"en": "Tariq ibn Ziyad", "bn": "তারিক ইবনে যিয়াদ"}, {"en": "Khalid ibn al-Walid", "bn": "খালিদ ইবনুল ওয়ালিদ"}, {"en": "‘Amr ibn al-‘As", "bn": "আমর ইবনুল আস"}, {"en": "Musa ibn Nusayr", "bn": "মুসা ইবনে নুসাইর"}], "correct": 0}', '{"en": "Jabal Tariq, \"Mount of Tariq\", became Gibraltar.", "bn": "জাবালুত তারিক, \"তারিকের পাহাড়\", থেকে জিব্রাল্টার।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
