INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('bf810508-1eb6-577f-a4c7-b64ab629dc62', '2cee54bf-f937-5d20-b193-3a38e5723842', 'choice', '{"en": "The shrine of Hazrat Shah Jalal is in…?", "bn": "হযরত শাহজালালের মাজার কোথায়?"}', '{"options": [{"en": "Sylhet", "bn": "সিলেট"}, {"en": "Chattogram", "bn": "চট্টগ্রাম"}, {"en": "Rajshahi", "bn": "রাজশাহী"}, {"en": "Khulna", "bn": "খুলনা"}], "correct": 0}', '{"en": "Shah Jalal came to Sylhet in the 14th century.", "bn": "শাহজালাল চতুর্দশ শতকে সিলেটে আসেন।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('362077c5-ea8b-5827-9d6a-f3786374dd7b', '2cee54bf-f937-5d20-b193-3a38e5723842', 'choice', '{"en": "The Sixty Dome Mosque (Shat Gombuj) is in…?", "bn": "ষাট গম্বুজ মসজিদ কোথায়?"}', '{"options": [{"en": "Bagerhat", "bn": "বাগেরহাট"}, {"en": "Dhaka", "bn": "ঢাকা"}, {"en": "Bogura", "bn": "বগুড়া"}, {"en": "Cumilla", "bn": "কুমিল্লা"}], "correct": 0}', '{"en": "Part of the Historic Mosque City of Bagerhat, a UNESCO World Heritage Site.", "bn": "বাগেরহাটের ঐতিহাসিক মসজিদের শহরের অংশ, ইউনেস্কো বিশ্ব ঐতিহ্য।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('a0613857-6a19-5fe3-aa96-fbb6b68d28f0', '2cee54bf-f937-5d20-b193-3a38e5723842', 'choice', '{"en": "Who built the Sixty Dome Mosque?", "bn": "ষাট গম্বুজ মসজিদ কে নির্মাণ করেন?"}', '{"options": [{"en": "Khan Jahan Ali", "bn": "খান জাহান আলী"}, {"en": "Shah Jalal", "bn": "শাহজালাল"}, {"en": "Isa Khan", "bn": "ঈসা খাঁ"}, {"en": "Shaista Khan", "bn": "শায়েস্তা খাঁ"}], "correct": 0}', '{"en": "Khan Jahan Ali, in the 15th century.", "bn": "খান জাহান আলী, পঞ্চদশ শতকে।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('e26a6edb-52b9-53be-a655-f41885c458fb', '2cee54bf-f937-5d20-b193-3a38e5723842', 'choice', '{"en": "What is the national mosque of Bangladesh?", "bn": "বাংলাদেশের জাতীয় মসজিদ কোনটি?"}', '{"options": [{"en": "Baitul Mukarram", "bn": "বায়তুল মোকাররম"}, {"en": "Star Mosque", "bn": "তারা মসজিদ"}, {"en": "Sixty Dome Mosque", "bn": "ষাট গম্বুজ মসজিদ"}, {"en": "Chawkbazar Mosque", "bn": "চকবাজার মসজিদ"}], "correct": 0}', '{"en": "Baitul Mukarram in Dhaka.", "bn": "ঢাকার বায়তুল মোকাররম।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b2b7ee42-5781-53bd-b0b0-5098a257bf01', '2cee54bf-f937-5d20-b193-3a38e5723842', 'choice', '{"en": "Around which year did Bakhtiyar Khalji bring Muslim rule to Bengal?", "bn": "প্রায় কোন সালে বখতিয়ার খলজি বাংলায় মুসলিম শাসনের সূচনা করেন?"}', '{"options": [{"en": "1204", "bn": "১২০৪"}, {"en": "1757", "bn": "১৭৫৭"}, {"en": "1526", "bn": "১৫২৬"}, {"en": "711", "bn": "৭১১"}], "correct": 0}', '{"en": "About 1204, taking Nadia from Lakshman Sen.", "bn": "প্রায় ১২০৪ সালে, লক্ষ্মণ সেনের কাছ থেকে নদীয়া জয় করে।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
