INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('25700e6c-29d9-5385-8fff-773805118eb7', '9f78f55b-eebf-56a2-98c9-f2714b09e0e6', 'choice', '{"en": "The Star Mosque (Tara Masjid) is in…?", "bn": "তারা মসজিদ কোথায়?"}', '{"options": [{"en": "Old Dhaka", "bn": "পুরান ঢাকা"}, {"en": "Sylhet", "bn": "সিলেট"}, {"en": "Bagerhat", "bn": "বাগেরহাট"}, {"en": "Rangpur", "bn": "রংপুর"}], "correct": 0}', '{"en": "In Armanitola, Old Dhaka, decorated with star mosaics.", "bn": "পুরান ঢাকার আরমানিটোলায়, তারকা নকশায় সজ্জিত।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('9977c0df-4708-5f52-988b-83a0f8d64ac2', '9f78f55b-eebf-56a2-98c9-f2714b09e0e6', 'choice', '{"en": "Where is the Bishwa Ijtema held?", "bn": "বিশ্ব ইজতেমা কোথায় অনুষ্ঠিত হয়?"}', '{"options": [{"en": "Tongi, by the Turag", "bn": "টঙ্গী, তুরাগের তীরে"}, {"en": "Cox’s Bazar", "bn": "কক্সবাজার"}, {"en": "Sylhet", "bn": "সিলেট"}, {"en": "Khulna", "bn": "খুলনা"}], "correct": 0}', '{"en": "On the bank of the Turag river at Tongi.", "bn": "টঙ্গীতে তুরাগ নদীর তীরে।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('36577efd-7d8c-59a6-8054-7d0531cde8e1', '9f78f55b-eebf-56a2-98c9-f2714b09e0e6', 'choice', '{"en": "Gaur was a capital of which kingdom?", "bn": "গৌড় কোন রাজ্যের রাজধানী ছিল?"}', '{"options": [{"en": "The Bengal Sultanate", "bn": "বাংলা সালতানাত"}, {"en": "The Mughal Empire", "bn": "মুঘল সাম্রাজ্য"}, {"en": "The Ottoman Empire", "bn": "উসমানি সাম্রাজ্য"}, {"en": "The Abbasids", "bn": "আব্বাসি"}], "correct": 0}', '{"en": "Gaur (and Pandua) served as capitals of the Bengal Sultanate.", "bn": "গৌড় (ও পাণ্ডুয়া) বাংলা সালতানাতের রাজধানী ছিল।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('146384f6-bd60-5726-ba87-ca36dc62822f', '9f78f55b-eebf-56a2-98c9-f2714b09e0e6', 'choice', '{"en": "Who made the first complete Bangla translation of the Quran?", "bn": "কুরআনের প্রথম পূর্ণাঙ্গ বাংলা অনুবাদ কে করেন?"}', '{"options": [{"en": "Girish Chandra Sen", "bn": "গিরিশচন্দ্র সেন"}, {"en": "Rabindranath Tagore", "bn": "রবীন্দ্রনাথ ঠাকুর"}, {"en": "Kazi Nazrul Islam", "bn": "কাজী নজরুল ইসলাম"}, {"en": "Muhammad Shahidullah", "bn": "মুহম্মদ শহীদুল্লাহ"}], "correct": 0}', '{"en": "Published 1881–1886.", "bn": "১৮৮১–১৮৮৬ সালে প্রকাশিত।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c1aac37f-0ed5-54e6-bb0e-5b25c6b8c51a', '9f78f55b-eebf-56a2-98c9-f2714b09e0e6', 'choice', '{"en": "Which Mughal-era fort in Old Dhaka has a mosque inside?", "bn": "পুরান ঢাকার কোন মুঘল আমলের দুর্গে মসজিদ আছে?"}', '{"options": [{"en": "Lalbagh Fort", "bn": "লালবাগ কেল্লা"}, {"en": "Red Fort", "bn": "লাল কেল্লা"}, {"en": "Agra Fort", "bn": "আগ্রা দুর্গ"}, {"en": "Idrakpur Fort", "bn": "ইদ্রাকপুর দুর্গ"}], "correct": 0}', '{"en": "Lalbagh Fort, begun in 1678, with its three-domed mosque.", "bn": "লালবাগ কেল্লা, ১৬৭৮ সালে নির্মাণ শুরু, তিন গম্বুজ মসজিদসহ।"}', NULL, 5) ON CONFLICT (id) DO NOTHING;
