INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ae3a29c3-50a2-505b-83e6-9ba4325cd48a', '588f4fe0-2f50-543a-83ee-72166e54f5d6', 'choice', '{"en": "The Sixty Dome Mosque (Shat Gombuj) is in…?", "bn": "ষাট গম্বুজ মসজিদ কোথায়?"}', '{"options": [{"en": "Bagerhat", "bn": "বাগেরহাট"}, {"en": "Dhaka", "bn": "ঢাকা"}, {"en": "Bogura", "bn": "বগুড়া"}, {"en": "Cumilla", "bn": "কুমিল্লা"}], "correct": 0}', '{"en": "Part of the Historic Mosque City of Bagerhat, a UNESCO World Heritage Site.", "bn": "বাগেরহাটের ঐতিহাসিক মসজিদের শহরের অংশ, ইউনেস্কো বিশ্ব ঐতিহ্য।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
