INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('14297e42-9ffc-557a-aaab-e2b8b7c9894b', '588f4fe0-2f50-543a-83ee-72166e54f5d6', 'choice', '{"en": "Gaur was a capital of which kingdom?", "bn": "গৌড় কোন রাজ্যের রাজধানী ছিল?"}', '{"options": [{"en": "The Bengal Sultanate", "bn": "বাংলা সালতানাত"}, {"en": "The Mughal Empire", "bn": "মুঘল সাম্রাজ্য"}, {"en": "The Ottoman Empire", "bn": "উসমানি সাম্রাজ্য"}, {"en": "The Abbasids", "bn": "আব্বাসি"}], "correct": 0}', '{"en": "Gaur (and Pandua) served as capitals of the Bengal Sultanate.", "bn": "গৌড় (ও পাণ্ডুয়া) বাংলা সালতানাতের রাজধানী ছিল।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
