INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f770be6c-cbd0-5390-99f0-5e6708d09840', 'bf6fc9b2-c795-5052-b1a3-fe8e17a0613e', 'choice', '{"en": "What is the holy book of Islam?", "bn": "ইসলামের পবিত্র গ্রন্থ কোনটি?"}', '{"options": [{"en": "The Quran", "bn": "কুরআন"}, {"en": "A dictionary", "bn": "অভিধান"}, {"en": "A storybook", "bn": "গল্পের বই"}, {"en": "A newspaper", "bn": "সংবাদপত্র"}], "correct": 0}', '{"en": "The Quran is the word of Allah.", "bn": "কুরআন আল্লাহর বাণী।"}', NULL, 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('00e1a0e1-27f0-51eb-b678-8dea3a2b7377', 'bf6fc9b2-c795-5052-b1a3-fe8e17a0613e', 'choice', '{"en": "Where do Muslims pray together?", "bn": "মুসলমানরা একসাথে কোথায় নামাজ পড়ে?"}', '{"options": [{"en": "Masjid", "bn": "মসজিদ"}, {"en": "Market", "bn": "বাজার"}, {"en": "Park", "bn": "পার্ক"}, {"en": "School", "bn": "স্কুল"}], "correct": 0}', '{"en": "The masjid is the house of Allah.", "bn": "মসজিদ আল্লাহর ঘর।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('1642f485-61fb-5bbc-b191-e115d4cdfb28', 'bf6fc9b2-c795-5052-b1a3-fe8e17a0613e', 'choice', '{"en": "How many times a day do Muslims pray?", "bn": "মুসলমানরা দিনে কতবার নামাজ পড়ে?"}', '{"options": [{"en": "1", "bn": "১"}, {"en": "3", "bn": "৩"}, {"en": "5", "bn": "৫"}, {"en": "10", "bn": "১০"}], "correct": 2}', '{"en": "Fajr, Dhuhr, Asr, Maghrib and Isha.", "bn": "ফজর, যোহর, আসর, মাগরিব ও ইশা।"}', NULL, 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f783e529-4693-5e67-9faf-1e22567fb329', 'bf6fc9b2-c795-5052-b1a3-fe8e17a0613e', 'choice', '{"en": "Which city has the Ka‘bah?", "bn": "কাবা কোন শহরে?"}', '{"options": [{"en": "Makkah", "bn": "মক্কা"}, {"en": "Dhaka", "bn": "ঢাকা"}, {"en": "Cairo", "bn": "কায়রো"}, {"en": "London", "bn": "লন্ডন"}], "correct": 0}', '{"en": "The Ka‘bah is in Makkah.", "bn": "কাবা মক্কায়।"}', NULL, 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('f3d68006-d1e8-5ce3-8a01-7a1ffd839519', 'bf6fc9b2-c795-5052-b1a3-fe8e17a0613e', 'choice', '{"en": "What do we say before eating?", "bn": "খাওয়ার আগে আমরা কী বলি?"}', '{"options": [{"en": "Bismillah", "bn": "বিসমিল্লাহ"}, {"en": "Goodbye", "bn": "বিদায়"}, {"en": "Hello", "bn": "হ্যালো"}, {"en": "Thank you", "bn": "ধন্যবাদ"}], "correct": 0}', '{"en": "Say Bismillah and eat with your right hand.", "bn": "বিসমিল্লাহ বলো এবং ডান হাতে খাও।"}', 'Sahih al-Bukhari 5376', 5) ON CONFLICT (id) DO NOTHING;
