INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('8e15ae87-5098-5ee9-8a7d-2616362a1aa7', '93510582-a224-5cfc-9a2f-05c2cc15da9a', 'choice', '{"en": "Who is the last prophet?", "bn": "শেষ নবী কে?"}', '{"options": [{"en": "Muhammad ﷺ", "bn": "মুহাম্মাদ ﷺ"}, {"en": "Musa", "bn": "মুসা"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Adam", "bn": "আদম"}], "correct": 0}', '{"en": "Muhammad ﷺ is the last prophet.", "bn": "মুহাম্মাদ ﷺ শেষ নবী।"}', 'Quran 33:40', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('010fff19-90e6-5da4-a88d-fb64eaf542ba', '93510582-a224-5cfc-9a2f-05c2cc15da9a', 'choice', '{"en": "What do we say when something good happens?", "bn": "ভালো কিছু ঘটলে আমরা কী বলি?"}', '{"options": [{"en": "Alhamdulillah", "bn": "আলহামদুলিল্লাহ"}, {"en": "Oops", "bn": "উফ"}, {"en": "Nothing", "bn": "কিছু না"}, {"en": "Goodbye", "bn": "বিদায়"}], "correct": 0}', '{"en": "Alhamdulillah: all praise is for Allah.", "bn": "আলহামদুলিল্লাহ: সব প্রশংসা আল্লাহর।"}', NULL, 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('383ef895-219e-526e-9fe3-d8a475890185', '93510582-a224-5cfc-9a2f-05c2cc15da9a', 'choice', '{"en": "In which language was the Quran revealed?", "bn": "কুরআন কোন ভাষায় নাজিল হয়েছে?"}', '{"options": [{"en": "Arabic", "bn": "আরবি"}, {"en": "English", "bn": "ইংরেজি"}, {"en": "Bangla", "bn": "বাংলা"}, {"en": "Urdu", "bn": "উর্দু"}], "correct": 0}', '{"en": "\"Indeed, We sent it down as an Arabic Quran.\"", "bn": "\"নিশ্চয়ই আমি একে আরবি কুরআন হিসেবে নাজিল করেছি।\""}', 'Quran 12:2', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('cf2aeadb-0970-5504-9a3f-519bd247fc33', '93510582-a224-5cfc-9a2f-05c2cc15da9a', 'choice', '{"en": "In which month do Muslims fast?", "bn": "মুসলমানরা কোন মাসে রোজা রাখে?"}', '{"options": [{"en": "Ramadan", "bn": "রমজান"}, {"en": "Muharram", "bn": "মহররম"}, {"en": "Rajab", "bn": "রজব"}, {"en": "Safar", "bn": "সফর"}], "correct": 0}', '{"en": "Fasting Ramadan is a pillar of Islam.", "bn": "রমজানের রোজা ইসলামের স্তম্ভ।"}', 'Quran 2:185', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('fe7fdb20-1793-551b-bd8b-ca462e429012', '93510582-a224-5cfc-9a2f-05c2cc15da9a', 'choice', '{"en": "Who created everything?", "bn": "সবকিছু কে সৃষ্টি করেছেন?"}', '{"options": [{"en": "Allah", "bn": "আল্লাহ"}, {"en": "People", "bn": "মানুষ"}, {"en": "Nobody", "bn": "কেউ না"}, {"en": "The sun", "bn": "সূর্য"}], "correct": 0}', '{"en": "\"Allah is the Creator of all things.\"", "bn": "\"আল্লাহ সবকিছুর স্রষ্টা।\""}', 'Quran 39:62', 5) ON CONFLICT (id) DO NOTHING;
