INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c1382071-5bf7-5c8b-b636-9087ab92859d', '5d57336d-1c7c-561e-9b03-98b4abcaefb0', 'choice', '{"en": "Who created everything?", "bn": "সবকিছু কে সৃষ্টি করেছেন?"}', '{"options": [{"en": "Allah", "bn": "আল্লাহ"}, {"en": "People", "bn": "মানুষ"}, {"en": "Nobody", "bn": "কেউ না"}, {"en": "The sun", "bn": "সূর্য"}], "correct": 0}', '{"en": "\"Allah is the Creator of all things.\"", "bn": "\"আল্লাহ সবকিছুর স্রষ্টা।\""}', 'Quran 39:62', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b4f64113-8dc2-5837-90d5-1aad8173a0f8', '5d57336d-1c7c-561e-9b03-98b4abcaefb0', 'choice', '{"en": "What is the holy book of Islam?", "bn": "ইসলামের পবিত্র গ্রন্থ কোনটি?"}', '{"options": [{"en": "The Quran", "bn": "কুরআন"}, {"en": "A dictionary", "bn": "অভিধান"}, {"en": "A storybook", "bn": "গল্পের বই"}, {"en": "A newspaper", "bn": "সংবাদপত্র"}], "correct": 0}', '{"en": "The Quran is the word of Allah.", "bn": "কুরআন আল্লাহর বাণী।"}', NULL, 6) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_units (id, title, description, color, icon, review_status, sort_order, section_id) VALUES ('c3f0686f-33fd-5559-ab56-9823c87aa1ba', '{"en": "Kids: Islam basics — part 2", "bn": "শিশুদের জন্য: ইসলামের প্রাথমিক বিষয় — পর্ব ২"}', '{}', '#fbc531', 'graduation-cap', 'in_review', 2, '390dcfa6-a698-506f-8676-f1467c296dd5') ON CONFLICT (id) DO NOTHING;
