INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('ed2ec754-ba2a-51c5-89f9-9f821665d9dd', '000a92eb-9e76-532e-b8e8-bdec2ec983cf', 'choice', '{"en": "What was the first word revealed of the Quran?", "bn": "কুরআনের প্রথম নাজিলকৃত শব্দ কী?"}', '{"options": [{"en": "Read (Iqra’)", "bn": "পড়ো (ইকরা)"}, {"en": "Pray", "bn": "নামাজ পড়ো"}, {"en": "Run", "bn": "দৌড়াও"}, {"en": "Sleep", "bn": "ঘুমাও"}], "correct": 0}', '{"en": "\"Read in the name of your Lord who created.\"", "bn": "\"পড়ো তোমার রবের নামে, যিনি সৃষ্টি করেছেন।\""}', 'Quran 96:1', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('42686600-f6ae-5751-8183-cbbdc185b9c4', '000a92eb-9e76-532e-b8e8-bdec2ec983cf', 'choice', '{"en": "Which direction do we face when we pray?", "bn": "নামাজে আমরা কোন দিকে মুখ করি?"}', '{"options": [{"en": "The Ka‘bah", "bn": "কাবার দিকে"}, {"en": "The sun", "bn": "সূর্যের দিকে"}, {"en": "The door", "bn": "দরজার দিকে"}, {"en": "Anywhere", "bn": "যেকোনো দিকে"}], "correct": 0}', '{"en": "The qiblah, the Ka‘bah in Makkah.", "bn": "কিবলা, মক্কার কাবা।"}', 'Quran 2:144', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('282ff5ec-3a67-507a-9bef-c88dd99fce40', '000a92eb-9e76-532e-b8e8-bdec2ec983cf', 'choice', '{"en": "Which prophet struck the sea with his staff and it parted?", "bn": "কোন নবী লাঠি দিয়ে সমুদ্রে আঘাত করলে তা ভাগ হয়ে যায়?"}', '{"options": [{"en": "Musa", "bn": "মুসা"}, {"en": "Nuh", "bn": "নুহ"}, {"en": "Isa", "bn": "ঈসা"}, {"en": "Yunus", "bn": "ইউনুস"}], "correct": 0}', '{"en": "\"Strike the sea with your staff,\" and it parted.", "bn": "\"তোমার লাঠি দিয়ে সমুদ্রে আঘাত করো,\" আর তা ভাগ হয়ে গেল।"}', 'Quran 26:63', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('d8e040f1-44b6-5f56-b82a-2b04d24b52e4', '000a92eb-9e76-532e-b8e8-bdec2ec983cf', 'choice', '{"en": "On which animal did the Prophet ﷺ make the Night Journey?", "bn": "নবী ﷺ কোন বাহনে মিরাজের রাতের সফর করেন?"}', '{"options": [{"en": "Al-Buraq", "bn": "বুরাক"}, {"en": "A camel", "bn": "উট"}, {"en": "A horse", "bn": "ঘোড়া"}, {"en": "An elephant", "bn": "হাতি"}], "correct": 0}', '{"en": "Al-Buraq, a white animal \"a little bigger than a donkey\".", "bn": "বুরাক, \"গাধার চেয়ে একটু বড়\" সাদা একটি প্রাণী।"}', 'Sahih Muslim 162', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('58251365-3d23-5741-8233-7aa3563bb70e', '000a92eb-9e76-532e-b8e8-bdec2ec983cf', 'choice', '{"en": "What is the blessed water in Makkah called?", "bn": "মক্কার বরকতময় পানির নাম কী?"}', '{"options": [{"en": "Zamzam", "bn": "যমযম"}, {"en": "Kawthar", "bn": "কাওসার"}, {"en": "Nile", "bn": "নীল"}, {"en": "Furat", "bn": "ফোরাত"}], "correct": 0}', '{"en": "Zamzam, which began with Hajar and baby Isma‘il.", "bn": "যমযম, যার শুরু হাজেরা ও শিশু ইসমাইলের ঘটনা থেকে।"}', 'Sahih al-Bukhari 3364', 5) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_lessons (id, unit_id, title, kind, sort_order) VALUES ('e7b9e91d-2700-5bd9-b574-134b011166e2', 'c3f0686f-33fd-5559-ab56-9823c87aa1ba', '{"en": "Part 2", "bn": "পর্ব ২"}', 'lesson', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('868b76e3-5ed4-5280-aab6-2fd3b266bebd', 'e7b9e91d-2700-5bd9-b574-134b011166e2', 'choice', '{"en": "What do we give before the Eid al-Fitr prayer?", "bn": "ঈদুল ফিতরের নামাজের আগে আমরা কী দিই?"}', '{"options": [{"en": "Zakat al-Fitr", "bn": "সদকাতুল ফিতর"}, {"en": "Gifts to the imam", "bn": "ইমামকে উপহার"}, {"en": "Nothing", "bn": "কিছু না"}, {"en": "Our toys", "bn": "আমাদের খেলনা"}], "correct": 0}', '{"en": "So the poor can also enjoy Eid.", "bn": "যাতে গরিবরাও ঈদ উপভোগ করতে পারে।"}', 'Sahih al-Bukhari 1503', 1) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('b8f417e6-0026-5e8b-b54c-4a8e5ec4318c', 'e7b9e91d-2700-5bd9-b574-134b011166e2', 'choice', '{"en": "What do we say before reading the Quran?", "bn": "কুরআন পড়ার আগে আমরা কী বলি?"}', '{"options": [{"en": "A‘udhu billahi min ash-shaytan ir-rajim", "bn": "আউযু বিল্লাহি মিনাশ শাইতানির রাজিম"}, {"en": "Goodbye", "bn": "বিদায়"}, {"en": "Ameen", "bn": "আমিন"}, {"en": "Ma‘as-salamah", "bn": "মাআস সালামা"}], "correct": 0}', '{"en": "\"When you recite the Quran, seek refuge in Allah from Satan, the outcast.\"", "bn": "\"যখন কুরআন পড়বে, বিতাড়িত শয়তান থেকে আল্লাহর আশ্রয় চাও।\""}', 'Quran 16:98', 2) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('c0de12ec-0cf0-5415-a621-f5d725bc26fb', 'e7b9e91d-2700-5bd9-b574-134b011166e2', 'choice', '{"en": "How many days does Ramadan have?", "bn": "রমজান কত দিনের?"}', '{"options": [{"en": "29 or 30", "bn": "২৯ বা ৩০"}, {"en": "7", "bn": "৭"}, {"en": "40", "bn": "৪০"}, {"en": "15", "bn": "১৫"}], "correct": 0}', '{"en": "A lunar month is 29 or 30 days, depending on the moon.", "bn": "চান্দ্র মাস চাঁদ অনুযায়ী ২৯ বা ৩০ দিন।"}', 'Sahih al-Bukhari 1907', 3) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('0131cbd4-9fcc-5372-b6dc-003ca20e03bb', 'e7b9e91d-2700-5bd9-b574-134b011166e2', 'choice', '{"en": "Which bird told Sulayman about the Queen of Saba?", "bn": "কোন পাখি সুলাইমানকে সাবার রানির খবর দেয়?"}', '{"options": [{"en": "The hoopoe (hudhud)", "bn": "হুদহুদ পাখি"}, {"en": "The crow", "bn": "কাক"}, {"en": "The eagle", "bn": "ঈগল"}, {"en": "The parrot", "bn": "টিয়া"}], "correct": 0}', '{"en": "\"…and he inspected the birds and said: Why do I not see the hoopoe?\"", "bn": "\"…তিনি পাখিদের খোঁজ নিলেন এবং বললেন: হুদহুদকে দেখছি না কেন?\""}', 'Quran 27:20', 4) ON CONFLICT (id) DO NOTHING;
INSERT INTO is_learn_items (id, lesson_id, type, prompt, data, explanation, source_ref, sort_order) VALUES ('dc7c6e0f-540e-5a7a-9d80-5125df94393b', 'e7b9e91d-2700-5bd9-b574-134b011166e2', 'choice', '{"en": "What should we do when someone says As-salamu alaykum?", "bn": "কেউ আসসালামু আলাইকুম বললে আমাদের কী করা উচিত?"}', '{"options": [{"en": "Reply: Wa alaykum as-salam", "bn": "জবাব দেওয়া: ওয়া আলাইকুমুস সালাম"}, {"en": "Ignore them", "bn": "উপেক্ষা করা"}, {"en": "Run away", "bn": "দৌড়ে পালানো"}, {"en": "Laugh", "bn": "হাসা"}], "correct": 0}', '{"en": "Replying to salam is a duty.", "bn": "সালামের জবাব দেওয়া কর্তব্য।"}', 'Quran 4:86', 5) ON CONFLICT (id) DO NOTHING;
